INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2011, '计算机网络', '单选', 39, '主机甲向主机乙发送一个(SYN= 1, seq= 11220)的TCP段，期望与主机乙建立TCP 2018年计算机408统考真题 第 4 页，共 8 页 2011年全国硕士研究生入学统—考试计算机科学与技术学科联考计算机学科专业基础综合试题 园蓝面图匿回回囡囡园 连接，若主机乙接受该连接请求，则主机乙向主机甲发送的正确的TCP段可能是 。', '[{"key": "A", "text": "(SYN= 0, ACK= 0, seq= 11221, ack = 11221)"}, {"key": "B", "text": "(SYN= 1, ACK= 1, seq= 11220, ack = 11220)"}, {"key": "C", "text": "(SYN= 1, ACK= 1, seq= 11221, ack = 11221)"}, {"key": "D", "text": "(SYN= 0, ACK= 0, seq= 11220, ack = 11220)"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2011 AND question_number=39);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2011, '计算机网络', '单选', 40, '主机甲与主机乙之间已建立一个TCP连接，主机甲向主机乙发送了3个连续的TCP段， 分别包含300B、400B和500B的有效载荷，第3个段的序号为900。若主机乙仅正确接收到第1段 和第3段，则主机乙发送给主机甲的确认序号是 。', '[{"key": "A", "text": "300"}, {"key": "B", "text": "500"}, {"key": "C", "text": "1200 二、综合应用题（第4147小题，共70分）"}, {"key": "D", "text": "1400"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2011 AND question_number=40);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2011, '数据结构', '综合应用', 41, '(8分）已知有6个顶点（顶点编号为os) 的有向带权图G, 其邻接矩阵A为上三角 矩阵，按行为主序（行优先）保存在如下的一维数组中。 1416 l=l=l=ls 要求： (1)写出图G的邻接矩阵A。 (2)画出有向带权图G。 =1=14131=1=1313 (3)求图G的关键路径，并计算该关键路径的长度。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2011 AND question_number=41);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2011, '数据结构', '综合应用', 42, '(15分）一个长度为L (L?'':l)的升序序列S, 处在第Lu2l个位置的数称为S的中位数。 例如，若序列Sl= (11, 13, 15, 17, 19), 则Sl的中位数是15, 两个序列的中位数是含它们所有元素的 升序序列的中位数。例如，若S2= (2, 4, 6, 8, 20), 则Sl和S2的中位数是11。现在有两个等长升序 序列A和B, 试设计一个在时间和空间两方面都尽可能高效的算法，找出两个序列A和B的中位数。 要求： (1)给出算法的基本设计思想。 (2)根据设计思想，采用C、C++或Java语言描述算法，关键之处给出注释。 (3)说明你所设计算法的时间复杂度和空间复杂度。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2011 AND question_number=42);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2011, '计算机组成原理', '综合应用', 43, 'Cll分）假定在一个8位字长的计算机中运行如下C程序段： unsignǧǨLJpt•. x=134.i unsigr1etiJnt. y=246; int rn=x; int n=y; unsigneti,,ǩI;t.. zl=x-:-y; unsigned int z2=x+y; int·kl=rri.::n; int k2=rn+n; 若编译器编译时将8个8位寄存器RlR8分别分配给变量x、y、m、n、zl、z2、kl和k2。 请回答下列问题。（提示：带符号整数用补码表示。） (1)执行上述程序段后，寄存器Rl、R5和R6的内容分别是什么（用十六进制表示）？ (2)执行上述程序段后，变量m和kl的值分别是多少（用十进制表示）？ (3)上述程序段涉及带符号整数加／减、无符号整数加／减运算，这四种运算能否利用同一个 加法器辅助电路实现？简述理由。 (4)计算机内部如何判断带符号整数加I减运算的结果是否发生溢出？上述程序段中，哪些带 2018年计算机408统考真题 第 5 页，共 8 页 符号整数运算语句的执行结果会发生溢出？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2011 AND question_number=43);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2011, '计算机组成原理', '综合应用', 44, '(12分）某计算机存储器按字节编址，虚拟（逻辑）地址空间大小为16MB, 主存（物 理）地址空间大小为1MB, 页面大小为4KB; Cache采用直接映射方式，共8行；主存与Cache 之间交换的块大小为32B。系统运行到某一时刻时，页表的部分内容和Cache的部分内容分别如 题44-a图、题44-b图所示，图中页框号及标记字段的内容为十六进制形式。 虚页号 有效位 页框号 。 I 06 I 04 23456 7 I 15 I 02 。 I 2B 。 I 32 ．．． ... ... ．．． ... ．．． ... ．．． 题44-a图 页表的部分内容 请回答下列问题。 行号 有效位 标记 。 I 020 。 23456 7 I OID I 105 I 064 I 14D 。 I 27A ．．． ... ．．． ... ．．． ．．． ．．． ... 题44-b图 Cache的部分内容 (1)虚拟地址共有几位，哪儿位表示虚页号？物理地址共有几位，哪几位表示页框号（物理页 号）？ (2)使用物理地址访问Cache时，物理地址应划分成哪儿个字段？要求说明每个字段的位数 及在物理地址中的位置。 (3)虚拟地址001C60H所在的页面是否在主存中？若在主存中，则该虚拟地址对应的物理 地址是什么？访问该地址时是否Cache命中？要求说明理由。 (4)假定为该机配置一个四路组相联的TLB共可存放8个页表项，若其当前内容（十六进 制）如题44-c图所示，则此时虚拟地址024BACH所在的页面是否存在主存中？要求说明理由。 组 有效 标 页框 有效 标 页框 有效 标 页框 有效 标 页框 号 位 记 号 位 记 号 位 记 号 位 记 号 I 11111111 l0s111I 产I : I 题44-c图 TLB的部分内容', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2011 AND question_number=44);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2011, '操作系统', '综合应用', 45, '(8分）某银行提供1个服务窗口和10个供顾客等待的座位。顾客到达银行时，若有空 座位，则到取号机上领取一个号，等待叫号。取号机每次仅允许一位顾客使用。当营业员空闲时， 通过叫号选取一位顾客，并为其服务。顾客和营业员的活动过程描述如下： cobegin process 顾客i 从取号机获取一个号码； 等待叫号； 获取服务； process 营业员 2018年计算机408统考真题 第 6 页，共 8 页 while (TRUE) 请添加必要的信号量和P、V (或wait()、signal())操作，实现上述过程中的互斥与同步。要 求写出完整的过程，说明信号量的含义并赋初值。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2011 AND question_number=45);
