INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2011, '计算机网络', '综合应用', 47, '(9分）某主机的MAC地址为00-15-CS-Cl-SE-28 , IP地址为10.2.128.100 (私有地 址）。题47-a图是网络拓扑，题47-b图是该主机进行Web请求的1个以太网数据帧前80B的十六 进制及ASCII码内容。 MTU=l500B  题47-a图 网络拓扑 0000 00 21 27 21 51 ee 00 15 c5 cl 5e 28 08 00 45 00 .!J!Q ... .. "(.. E. 0010 01 ef 11 3b 40 00 80 06 ba 9d Oa 02 80 64 40 aa ... :@ ... ….. d@. 0020 62 20 04 ffOO 50 eO e2 00 fa 7b f9 f8 05 50 18 b…P .. .. { ... P. 0030 fa f() la c4 00 00 47 45 54 20 2f72 66 63 2e 68 ...... GE T /rfc.h 0040 74 6d 6c 20 48 54 54 50 2f31 2e 31 Od Oa 41 63 tml HTTP /1.1..Ac 题47-b图 以太网数据帧（前80B) 请参考图中的数据回答以下问题。 (1) Web服务器的IP地址是什么？该主机的默认网关的MAC地址是什么？ (2)该主机在构造题47-b图的数据帧时，使用什么协议确定目的MAC地址？封装该协议请 求报文的以太网帧的目的MAC地址是什么？ (3)假设HTTP/1.1协议以持续的非流水线方式工作，一次请求－响应时间为RTT , rfc.html 页面引用了5个JPEG小图像，则从发出题47-b图中的Web请求开始到浏览器收到全部内容为止， 需要多少个RTT? (4)该帧所封装的IP分组经过路由器R转发时，需修改IP分组头中的哪些字段？ 2018年计算机408统考真题 第 7 页，共 8 页 注： 以太网数据帧结构和IP分组头结构分别如题47-c图、题47-d图所示。 6B 目的MAC 地址 6B 2B 源MAC 地址 I 类型 1 题47-c图 以太网帧结构 46-1500B 数据 上七牛寺0 8 16 24 31 I I I I I I I I I I I I I I I I I I I I I I I I I I I I I I I I I 版本It言I 服务类型 标识 标志I 牛存时间(TTL)j 协议 源IP地址 目的IP地址 总长度 片偏移 头部校验和 题47-d图 IP分组头结构 4B CRC 2018年计算机408统考真题 第 8 页，共 8 页', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2011 AND question_number=47);
