INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '单选', 24, '中断处理和子程序调用都需要压栈以保护现场，中断处理一定会保存而子程序调用不 需要保存其内容的是 。', '[{"key": "A", "text": "程序计数器"}, {"key": "B", "text": "程序状态字寄存器 c. 通用数据寄存器"}, {"key": "D", "text": "通用地址寄存器"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=24);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '单选', 25, '下列关于虚拟存储器的叙述中，正确的是 。', '[{"key": "A", "text": "虚拟存储只能基于连续分配技术"}, {"key": "B", "text": "虚拟存储只能基于非连续分配技术"}, {"key": "C", "text": "虚拟存储容量只受外存容量的限制"}, {"key": "D", "text": "虚拟存储容量只受内存容量的限制"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=25);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '单选', 26, '操作系统的1/0子系统通常由四个层次组成，每一层明确定义了与邻近层次的接口。 2012年计算机408统考真题 第 3 页，共 8 页 其合理的层次组织排列顺序是', '[{"key": "A", "text": "用户级I/0软件、设备无关软件、设备驱动程序、中断处理程序"}, {"key": "B", "text": "用户级I/0软件、设备无关软件、中断处理程序、设备驱动程序"}, {"key": "C", "text": "用户级I/0软件、设备驱动程序、设备无关软件、中断处理程序"}, {"key": "D", "text": "用户级1/0软件、中断处理程序、设备无关软件、设备驱动程序"}]', 'A', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=26);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '单选', 27, '假设5 个进程P。、P 1、P2、P3、P4 共享三类资源R1、R2、R3 , 这些资源总数分别为18、 6、22。TO时刻的资源分配情况如下表所示，此时存在的一个安全序列是 。 已分配资源 资源最大需求 进程 R1 R2 R3 R, p。 3 2 3 5 P1 4 。 3 5 P2 4 。 5 4 Pi 2 。 4 4 P4 3 1 4 4', '[{"key": "A", "text": "Po, P2, P4, Pr, P3"}, {"key": "B", "text": "P 1, Po, P3, P4, P2"}, {"key": "C", "text": "P2, P1, Po, P3, P4"}, {"key": "D", "text": "P3, P4, P2, P 1, P。 R2 5 3 。 2 2 R3 10 6 II 5 4"}]', 'D', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=27);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '单选', 28, '若一个用户进程通过read系统调用读取一个磁盘文件中的数据，则下列关于此过程的 叙述中，正确的是 。 I. 若该文件的数据不在内存中，则该进程进入睡眠等待状态 II. 请求read系统调用会导致CPU从用户态切换到核心态 III. read系统调用的参数应包含文件的名称', '[{"key": "A", "text": "仅I、II"}, {"key": "B", "text": "仅I、III"}, {"key": "C", "text": "仅II、III"}, {"key": "D", "text": "I、II 和III"}]', 'A', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=28);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '单选', 29, '一个多道批处理系统中仅有P 1 和P2 两个作业，P2 比P1晚5ms到达，它们的计算和1/0 操作顺序如下： P i : 计算60ms, 1/0 80ms, 计算20ms P2: 计算120ms, 1/0 40ms, 计算40ms 若不考虑调度和切换时间，则完成两个作业需要的时间最少是', '[{"key": "A", "text": "240ms"}, {"key": "B", "text": "260ms"}, {"key": "C", "text": "340ms"}, {"key": "D", "text": "360ms"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=29);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '单选', 30, '若某单处理器多进程系统中有多个就绪态进程，则下列关于处理机调度的叙述中，错 误的是', '[{"key": "A", "text": "在进程结束时能进行处理机调度"}, {"key": "B", "text": "创建新进程后能进行处理机调度"}, {"key": "C", "text": "在进程处于临界区时不能进行处理机调度"}, {"key": "D", "text": "在系统调用完成并返回用户态时能进行处理机调度"}]', 'C', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=30);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '单选', 31, '下列关于进程和线程的叙述中，正确的是 。', '[{"key": "A", "text": "不管系统是否支待线程，进程都是资源分配的基本单位"}, {"key": "B", "text": "线程是资源分配的基本单位，进程是调度的基本单位"}, {"key": "C", "text": "系统级线程和用户级线程的切换都需要内核的支持"}, {"key": "D", "text": "同一进程中的各个线程拥有各自不同的地址空间"}]', 'A', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=31);
