INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '计算机网络', '单选', 36, '两台主机之间的数据链路层采用后退N帧协议(GBN)传输数据， 数据传输速率为 16kbps, 单向传播时延为270ms, 数据帧长度范围是12sƟs12字节，接收方总是以与数据帧等 长的帧进行确认。为使信道利用率达到最高， 帧序号的比特数至少为 。', '[{"key": "A", "text": "5"}, {"key": "B", "text": "4"}, {"key": "C", "text": "3"}, {"key": "D", "text": "2"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=36);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '计算机网络', '单选', 37, '下列关千IP路由器功能的描述中，正确的是 。 I. 运行路由协议，设置路由表 II. 监测到拥塞时，合理丢弃IP分组 III. 对收到的IP分组头进行差错校验，确保传输的IP分组不丢失 IV. 根据收到的IP分组的目的IP地址，将其转发到合适的输出线路上', '[{"key": "A", "text": "仅III、.IV c. 仅I、II、IV"}]', 'C', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=37);
