INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '计算机网络', '单选', 39, '某主机的IP地址为180.80.77.55, 子网掩码为255.255.252.0。若该主机向其所在子网 发送广播分组，则目的地址可以是', '[{"key": "A", "text": "180.80.76.0"}, {"key": "B", "text": "180.80.76.255"}, {"key": "C", "text": "180.80.77.255"}, {"key": "D", "text": "180.80.79.255"}]', 'D', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=39);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '计算机网络', '单选', 40, '若用户1 与用户2之间发送和接收电子邮件的过程如下图所示，则图中＠、＠、©阶 段分别使用的应用层协议可以是 。 用户l', '[{"key": "A", "text": "SMTP、SMTP、SMTP"}, {"key": "C", "text": "POP3、SMTP、SMTP 用户1的 邮件服务器 二、综合应用题（第41-47题，共70分） 用户2的 邮件服务器 用户2 —©一§"}, {"key": "B", "text": "POP3、SMTP、POP3"}, {"key": "D", "text": "SMTP 、SMTP 、POP3"}]', 'D', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=40);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '数据结构', '综合应用', 41, '设有6个有序表A、B、C、D、E、F, 分别含有10、35、40、50、60和200个数据 元素，各表中元素按升序排列。要求通过5次两两合并，将6个表最终合并成1个升序表，并 在最坏情况下比较的总次数达到最小。请回答下列问题。 1)给出完整的合并过程，并求出最坏情况下比较的总次数。 2)根据你的合并过程，描述N(N?::2)个不等长升序表的合并策略， 并说明理由。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=41);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '数据结构', '综合应用', 42, '假定采用带头结点的单链表保存单词，当两个单词有相同的后缀时，则可共享相同的 2012年计算机408统考真题 第 5 页，共 8 页 后缀存储空间， 例如，"loading"和"being" 的存储映像如下图所示。 strl str2 设strl和str2分别指向两个单词所在单链表的头结点，链表结点结构为I 扫ta I ne灶I, 请设计 一个时间上尽可能高效的算法，找出由strl和str2 所指向两个链表共同后缀的起始位置（如图 中字符i 所在结点的位置p)。要求： 1)给出算法的基本设计思想。 2)根据设计思想，采用C或C+ +或Java语言描述算法，关键之处给出注释。 3)说明你所设计算法的时间复杂度。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=42);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '计算机组成原理', '综合应用', 43, '假定某计算机的CPU主频为80MHz,CPI为4, 平均每条指令访存1.5次，主存与Cache 之间交换的块大小为16B, Cache的命中率为99%, 存储器总线宽度为32位。请回答下列问题。 1) 该计算机的MIPS数是多少？平均每秒Cache缺失的次数是多少？在不考虑DMA传送 的情况下，主存带宽至少达到多少才能满足CPU的访存要求？ 2)假定在Cache缺失的情况下访问主存时，存在0.0005%的缺页率，则CPU平均每秒产 生多少次缺页异常？若页面大小为4KB, 每次缺页都需要访问磁盘，访问磁盘时DMA传送采 用周期挪用方式，磁盘1/0接口的数据缓冲寄存器为32 位，则磁盘1/0接口平均每秒发出的 DMA请求次数至少是多少？ 3) CPU和DMA控制器同时要求使用存储器总线时，哪个优先级更高？为什么？ 4)为了提高性能，主存采用四体低位交叉存储模式，工作时每1/4个存储周期启动一个体。 若每个体的存储周期为50ns, 则该主存能提供的最大带宽是多少？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=43);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '计算机组成原理', '综合应用', 44, '某16位计算机中，带符号整数用补码表示，数据Cache和指令Cache分离。题44表 给出了指令系统中部分指令格式， 其中Rs和Rd表示寄存器，mem表示存储单元地址，(x)表 示寄存器x或存储单元x的内容。 指令系统中部分指令格式 名称 指令的汇编格式 指令功能 加法指令 ADD Rs, Rd (Rs)+ (Rd)->Rd 算术I逻辑左移 SHL Rd 2*(Rd)->Rd 算术右移 SHR Rd (Rd)/2->Rd 取数指令 LOAD Rd,mem (mem)->Rd 存数指令 STORE Rs, mem (Rs)->mem 该计算机采用5段流水方式执行指令，各流水段分别是取指OF)、译码／读寄存器(I D)、 执行／计算有效地址(EX)、访问存储器CM) 和结果写回寄存器(WB),流水线采用 “ 按序发 射，按序完成 ” 方式，没有采用转发技术处理数据相关，并且同一个寄存器的读和写操作不能 在同一个时钟周期内进行。请回答下列问题： 1)若int型变量x的值为-513, 存放在寄存器Rl中，则执行指令"SHR Rl"后，Rl 的 内容是多少？ （用十六进制表示） 2)若某个时间段中，有连续的4条指令进入流水线，在其执行过程中没有发生任何阻塞， 则执行这4 条指令所需的时钟周期数为多少？ 2012年计算机408统考真题 第 6 页，共 8 页 3)若高级语言程序中某赋值语句为X =a+ b, X、a和b均为int型变量，它们的存储单 元地址分别表示为[x]、[a]和[b]。该语句对应的指令序列及其在指令流水线中的执行过程如下 图所示。 I1 LOAD Ii LOAD l3 ADD 14 STORE 指令 I 2 3 4 5 6 I1 IF ID EX M WB Ii IF ID EX M WB !3 IF Li 时间单元 7 8 ID EX IF Rl, [a] R2, [b] Rl,R2 R2, [x] 9 10 M WB 11 12 ID EX 则这4条指令执行过程中，l3 的ID段和l4的IF段被阻塞的原因各是什么？ 13 14 M WB 4)若高级语言程序中某赋值语句为x =x*2 + a, x和a均为unsigned int类型变量，它们的 存储单元地址分别表示为[x]、[a], 则执行这条语句至少需要多少个时钟周期？要求模仿题44 图画出这条语句对应的指令序列及其在流水线中的执行过程示意图。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=44);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '综合应用', 45, '某请求分页系统的局部页面置换策略如下：系统从0 时刻开始扫描，每隔5个时间单 位扫描一轮驻留集（扫描时间忽略不计），本轮没有被访问过的页框将被系统回收，并放入 到空闲页框链尾，其中内容在下一次分配之前不被清空。当发生缺页时，如果该页曾被使用 过且还在空闲页链表中，那么重新放回进程的驻留集中；否则，从空闲页框链表头部取出一 个页框。 假设不考虑其他进程的影响和系统开销。初始时进程驻留集为空。目前系统空闲页框链表 中页框号依次为32、15、21、41。进程P依次访问的＜虚拟页号，访问时刻＞是<I,I>, <3, 2>, <O, 4>, <O, 6>, <I, 11>, <O, 13>, <2, 14>。请回答下列问题。 1)访问<0,4>时，对应的页框号是什么？说明理由。 2)访问<I,11>时，对应的页框号是什么？说明理由。 3)访问<2,14>时，对应的页框号是什么？说明理由。 4)该策略是否适合于时间局部性好的程序？说明理由。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=45);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '操作系统', '综合应用', 46, '某文件系统空间的最大容量为4TB CITB = 240B), 以磁盘块为基本分配单位。磁盘块 大小为IKB。文件控制块(FCB)包含一个512B 的索引表区。请回答下列问题。 1)假设索引表区仅采用直接索引结构，索引表区存放文件占用的磁盘块号，索引表项中 块号最少占多少字节？可支持的单个文件最大长度是多少字节？ 2)假设索引表区采用如下结构：第0-7字节采用＜起始块号，块数＞格式表示文件创建时 预分配的连续存储空间，其中起始块号占6B , 块数占2B; 剩余504字节采用直接索引结构， 一个索引项占6B, 那么可支持的单个文件最大长度是多少字节？为了使单个文件的长度达到最 大，请指出起始块号和块数分别所占字节数的合理值并说明理由。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=46);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2012, '计算机网络', '综合应用', 47, '主机H通过快速以太网连接Internet, IP地址为192.168.0.8, 服务器S 的IP地址为 211.68.71.80。H与S使用TCP通信时，在H上捕获的其中5个IP分组如题47-a表所示。 2012年计算机408统考真题 第 7 页，共 8 页 编号 2 3 4 5 题47-a表 IP 分组的前40字节内容（十六进制） 45 00 00 30 Ol 9b 40 00 80 06 lde8 c0a8 00 08 d3 44 4750 Ob d9 13 88 84 6b 41 c5 00 00 00 00 70 02 43 80 5d bO 00 00 43 0000 30 00 00 40 00 31 066e 83 d3 44 4750 c0a8 00 08 13 88 Ob d9 eO 59 9fe f 84 6b 41 c6 70 12 16 dO 37 el 00 00 45 00 00 28 019c40 00 80061def c0a8 00 08 d3 44 4750 Ob d9 13 88 84 6b 41 c6 eO 59 9fU 50 fU 43 80 2 b 32 00 00 45 0000 3 8 019d 4000 8006 ld de c0a8 00 08 d3 44 4750 Ob d9 13 88 84 6b 41 c6 eO 59 9fU 50 18 43 80 e6 55 00 00 45 0000 28 68 11 40 00 3106067a d3 44 4750 c0a8 00 08 13 88 Ob d9 eO 59 9fU 84 6b 41 d6 50 10 16 dO 57 d2 00 00 回答下列问题。 1) 题47-a 表中的IP 分组中，哪几个是由H 发送的？哪儿个完成了TCP 连接建立过程？ 哪儿个在通过快速以太网传输时进行了填充？ 2) 根据题47-a 表中的IP 分组，分析S 已经收到的应用层数据字节数是多少？ 3) 若题47-a 表中的某个IP 分组在S 发出时的前40 字节如题47-b 表所示，则该IP 分组到 达H 时经过了多少个路由器？ 题47-b表 来自S的分组 45 00 00 28 68 11 40 00 40 06 ec ad d3 44 47 50 ca 76 0 I 06 13 88 al 08 eO 59 9fil 84 6b 41 d6 50 10 16 dO b7 d6 00 00 注：IP 分组头和TCP 段头结构分别如题47-a图和题47-b 图所示。 bit O 8 16 24 3 I I I I I I I I I I I I I I I I I I I I I I I I I I I I I I I I I I 版本i 言I 服务类型 总长度 标识 标志I 片偏移 生存时间(TTL)I 协议 头部校验和 源IP地址 目的IP地址 题47-a 图 IP 分组头结构 32位 位 0 8 16 24 31 ! I 源端口 目的端口 序号 I 20{ 的 TCP 固定首部 首部 数据 保留 窗口 偏移 检验和 紧急指针 选项（长度可变） 填充 题47-b 图 TCP 段头结构 2012年计算机408统考真题 第 8 页，共 8 页', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2012 AND question_number=47);
