INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '计算机网络', '单选', 34, '某以太网拓扑及交换机当前转发表如下图所示，主机OO-el-dS-00-23-al 向主机 00-e l -dS-00-23-c 1发送l个数据帧，主机OO-el-d5-00-23-cl收到该帧后，向主机00-e1-dS-00-23-a 1 发送1个确认帧，交换机对这两个帧的转发端口分别是 交换机 目的地址 端口 00-e l-d5-00-23-b I 2 00-e 1-dS-00-23-al OO-el-dS-00-23-bl 00-e l-dS-00-23-c 1', '[{"key": "A", "text": "{3}禾廿{1}"}, {"key": "B", "text": "{2, 3}禾日{1}"}, {"key": "C", "text": "{2,3}禾D{1, 2}"}, {"key": "D", "text": "{ 1, 2, 3}禾D{l}"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=34);
