INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '计算机网络', '单选', 36, '主机甲与主机乙之间使用后退N帧协议CGBN)传输数据，甲的发送窗口尺寸为1000, 数据帧长为1000字节，信道带宽为lOOMbps, 乙每收到一个数据帧立即利用一个短帧（忽略其 传输延迟）进行确认，若甲、乙之间的单向传播延迟是50ms, 则甲可以达到的最大平均数据传 输速率约为', '[{"key": "A", "text": "lOMbps"}, {"key": "B", "text": "20Mbps"}, {"key": "C", "text": "80Mbps"}, {"key": "D", "text": "lOOMbps"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=36);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '计算机网络', '单选', 37, '站点A、B、C通过CDMA共享链路，A、B、C的码片序列(chipping sequence) 分 别是(1,1, I, 1)、(1,-I, I, -1)和(1,I, -1, -1)。若C从链路上收到的序列是(2,0, 2, 0, 0, -2, 0, -2, 0, 2, 0, 2), 则C收到A发送的数据是 。', '[{"key": "A", "text": "000"}, {"key": "B", "text": "101"}, {"key": "C", "text": "110"}, {"key": "D", "text": "111"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=37);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '计算机网络', '单选', 38, '主机甲和主机乙已建立了TCP连接，甲始终以MSS = 1KB大小的段发送数据，并一 直有数据发送； 乙每收到一个数据段都会发出一个接收窗口为10KB的确认段。若甲在t时刻 发生超时时拥塞窗口为8KB, 则从t时刻起，不再发生超时的情况下，经过10个RTT后，甲 的发送窗口是', '[{"key": "A", "text": "10KB"}, {"key": "B", "text": "12KB"}, {"key": "C", "text": "14KB"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=38);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '计算机网络', '单选', 39, '下列关千UDP协议的叙述中，正确的是 。 I. 提供无连接服务 D. 15KB 2014年计算机408统考真题 第 4 页，共 7 页 II. 提供复用I分用服务 III. 通过差错校验， 保障可靠数据传输', '[{"key": "A", "text": "仅I"}, {"key": "B", "text": "仅I、II ·C. 仅II、III"}, {"key": "D", "text": "I、II、III"}]', 'DAACB', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=39);
