INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '数据结构', '综合应用', 41, '(13分）二叉树的带权路径长度(WPL)是二叉树中所有叶结点的带权路径长度之和。 给定一棵二叉树T , 采用二叉链表存储，结点结构如下： I left I weight I right 其中叶结点的weight域保存该结点的非负权值。设root为指向T的根结点的指针，请设计求T 的WPL的算法，要求： 1)给出算法的基本设计思想。 2)使用C或C++语言， 给出二叉树结点的数据类型定义。 3)根据设计思想，采用C或C++语言描述算法，关键之处给出注释。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=41);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '数据结构', '综合应用', 42, 'Clo分）某网络中的路由器运行OSPF路由协议，题42表是路由器Rl维护的主要链 路状态信息(LSI),题42图是根据题42表及Rl的接口名构造出来的网络拓扑。 题42表 R1 所维护的LSI R1 的LSI R2 的LSI R3自勺LSI R4 的LSI 备 注 Router ID 10.1.1.l 10.1.1.2 10.1.1.5 10.1.1.6 标识路由器的IP 地址 ID 10.1.1.2 10.1.1.1 10.1.1.6 10.1.1.5 所连路由器的Router ID Link! IP I 0.1.1.1 10.1.1.2 10.1.1.5 I 0.1.1.6 Link! 的本地IP 地址 Metric 3 3 6 6 Link! 的费用 ID 10.1.1.5 10.1.1.6 10.1.1.l 10.1.1.2 所连路由器的Router ID Link2 IP 10.1.1.9 J0.1.1.13 10.1.l.10 10.1.1.14 Link2 的本地IP 地址 Metric 2 4 2 4 Link2 的费用 Prefix 192.1. 1.0/24 192.1.6.0/24 I 92.1.5.0/24 192.1.7.0/24 直连网络Nell 的网络前缀 Net! Metric I I I I 到达直连网络Net! 的费用 LO 10 I I I IO.I I 2 3 』0.1.1 10 4 6 101.1.5 10 11 6 题42 图 Rl 构造的网络拓扑 请回答下列问题。 1)本题中的网络可抽象为数据结构中的哪种逻辑结构？ 2)针对题42表中的内容，设计合理的链式存储结构， 以保存题42表中的链路状态信息 2014年计算机408统考真题 第 5 页，共 7 页 2019 年器回匿器器 计算机专业基础综合考试真题思路分析 (LSI)。要求给出链式存储结构的数据类型定义，并画出对应题42表的链式存储结构示意图（示 意图中可仅以ID标识结点）。 3)按照迪杰斯特拉( Dijkstra)算法的策略，依次给出Rl到达题42图中子网192.1.x.x的 最短路径及费用。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=42);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '计算机组成原理', '综合应用', 43, '( 9分）请根据题42描述的网络，继续回答下列问题。 1)假设路由表结构如下表所示，请给出题42图中Rl的路由表，要求包括到达题42图中 子网192.1.x.x的路由，且路由表中的路由项尽可能少。 目的网络 下一跳 接口 2)当主机192.1.1.130向主机192.1.7.211发送一个TTL = 64的IP分组时，Rl通过哪个接 口转发该IP分组？主机192.1.7.211收到的IP分组TTL是多少？ 3)若Rl增加一条Metric为10的链路连接Internet, 则题42表中Rl的LSI需要增加哪些 信息？ 44. 02分）某程序中有如下循环代码段P: "for(int i = O; i <N; i++) sum+=A[i];"。假设编 译时变量sum和i分别分配在寄存器Rl和R2中。常量N在寄存器R6 中，数组A的首地址在 寄存器R3中。程序段P起始地址为0804 8100H, 对应的汇编代码和机器代码如下表所示。 编号 地址 机器代码 汇编代码 注释 I 08048100H 00022080H loop: s11 R4, R2, 2 (R2)«28R4 2 08048104H 00083020H add R4, R4, R3 (R4) + (R3) 分R4 3 08048108H 8C850000H load RS, O(R4) ((R4) + 0) 今RS 4 0804810CH 00250820H add RI, RI, R5 (RI)+ (RS) 今RI 5 08048110H 20420001H addR2, R2, I (R2) + 1 今R2 6 08048 114H 1446FFFAH bne R2, R6, loop if(R2)!=(R6) goto loop 执行上述代码的计算机M采用32 位定长指令字，其中分支指令bne采用如下格式： I " OP " I " R s 21 I " Rd 16 1 15 OFFSET l _, 。 OP为操作码；Rs和Rd为寄存器编号；OFFSET 为偏移鼠，用补码表示。请回答下列问题，并 说明理由。 1) M的存储器编址单位是什么？ 2)已知s11指令实现左移功能，数组A中每个元素占多少位？ 3)表中bne指令的OFFS ET字段的值是多少？已知bne指令采用相对寻址方式，当前PC 内容为bne指令地址，通过分析表中指令地址和bne指令内容，推断出bne指令的转移目标地 址计算公式。 4)若M采用如下 “按序发射、按序完成 ” 的5级指令流水线：IF (取值）、ID (译码及取 数）、EXE (执行）、ME M (访存）、WB (写回寄存器），且硬件不采取任何转发措施，分支指 令的执行均引起3个时钟周期的阻塞，则P中哪些指令的执行会由于数据相关而发生流水线阻 塞？哪条指令的执行会发生控制冒险？为什么指令l的执行不会因为与指令5的数据相关而发 生阻塞？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=43);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '操作系统', '综合应用', 45, '假设对于44 题中的计算机M和程序P的机器代码，M采用页式虚拟存储管理；P开 始执行时，(Rl) = (R2) = 0, (R6 ) = 1000, 其机器代码已调入主存但不在Cache中；数组A未调 入主存，且所有数组元素在同一页，并存储在磁盘同一个扇区。请回答下列问题并说明理由。 2014年计算机408统考真题 第 6 页，共 7 页 1) p执行结束时，R2 的内容是多少？ 2) M 的指令Cache 和数据Cache 分离。若指令Cache 共有16 行，Cache 和主存交换的块 大小为32 字节，则其数据区的容量是多少？若仅考虑程序段P 的执行，则指令Cache 的命中率 为多少？ 3) p在执行过程中，哪条指令的执行可能发生溢出异常？哪条指令的执行可能产生缺页异 常？对于数组A的访问，需要读磁盘和TLB至少各多少次？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=45);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '操作系统', '综合应用', 46, '文件F由200 条记录组成，记录从1 开始编号。用户打开文件后，欲将内存中的一条 记录插入到文件F中，作为其第30条记录。请回答下列问题，并说明理由。 1)若文件系统采用连续分配方式，每个磁盘块存放一条记录，文件F存储区域前后均有 足够的空闲磁盘空间，则完成上述插入操作最少需要访问多少次磁盘块? F的文件控制块内容 会发生哪些改变？ 2)若文件系统采用链接分配方式，每个磁盘块存放一条记录和一个链接指针，则完成上 述插入操作需要访问多少次磁盘块？若每个存储块大小为1KB, 其中4 字节存放链接指针，则 该文件系统支持的文件最大长度是多少？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=46);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2014, '计算机网络', '综合应用', 47, '系统中有多个生产者进程和多个消费者进程，共享一个能存放1000 件产品的环形缓冲 区（初始为空）。当缓冲区未满时，生产者进程可以放入其生产的一件产品，否则等待；当缓冲 区未空时，消费者进程可以从缓冲区取走一件产品，否则等待。要求一个消费者进程从缓冲区 连续取出10 件产品后，其他消费者进程才可以取产品。请使用信号量P, V C或wait(), signal()) 操作实现进程间的互斥与同步，要求写出完整的过程，并说明所用信号量的含义和初值。 2014年计算机408统考真题 第 7 页，共 7 页', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2014 AND question_number=47);
