INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2017, '操作系统', '单选', 25, '某计算机按字节编址，其动态分区内存管理采用最佳适应算法，每次分配和回收内存 后都对空闲分区链重新排序。当前空闲分区信息如下表所示。 分区起始地址 分区大小 20K 40KB SOOK 80KB IOOOK 100KB 200K 200KB 回收起始地址为60K、大小为140KB的分区后，系统中空闲分区的数量、空闲分区链第一 个分区的起始地址和大小分别是 。 2017年计算机408统考真题 第 3 页，共 8 页 2017年全国硕士研究生入学统一考试计算机科学与技术学科联考计算机学科专业基础综合试题 口口哩啜醒匿墨圈固囡圉圈', '[{"key": "A", "text": "3、20K、380KB"}, {"key": "B", "text": "3、SOOK、80KB"}, {"key": "C", "text": "4、20K、180KB"}, {"key": "D", "text": "4、500K、80KB"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2017 AND question_number=25);
