INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2017, '计算机网络', '单选', 40, '下列关于FTP协议的叙述中，错误的是', '[{"key": "A", "text": "数据连接在每次数据传输完毕后就关闭"}, {"key": "B", "text": "控制连接在整个会话期间保持打开状态"}, {"key": "C", "text": "服务器与客户端的TCP20 端口建立数据连接"}, {"key": "D", "text": "客户端与服务器的TCP21 端口建立控制连接 二、综合应用题（第4147 小题，共70 分）"}, {"key": "D", "text": "165ms"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2017 AND question_number=40);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2017, '数据结构', '综合应用', 41, '(15分）请设计一个算法，将给定的表达式树（二叉树）转换为等价的中缀表达式（通 过括号反映操作符的计算次序）并输出。例如，当下列两棵表达式树作为算法的输入时，输出 的等价中缀表达式分别为(a+b)*(c*(-d))和(a*b)+(-(c-d))。 二叉树结点定义如下： 七ypedef struct node{ char data[lO]; S 七rue七node·*left, *right; II存储操作数或操作符 2017年计算机408统考真题 第 5 页，共 8 页 )BTree; 要求： (1)给出算法的基本设计思想。 (2) 根据设计思想，采用C 或C++语言描述算法，关键之处给出注释。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2017 AND question_number=41);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2017, '数据结构', '综合应用', 42, '(8 分）使用Prim (普里姆）算法求带权连通图的最小（代价）生成树(MST) 。请回 答下列问题。 (1)对下列图G, 从顶点A 开始求G 的MST, 依次给出按算法选出的边。 (2) 图G 的MST 是唯一的吗？ (3)对任意的带权连通图，满足什么条件时，其MST 是唯一的？ n+l位＿', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2017 AND question_number=42);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2017, '计算机组成原理', '综合应用', 43, 'C 13 分）已知f(n)=吝2i= 2n+l -1 = 11…1B'' 计算f(n) 的C 语言函数fl 如下： int fl (unsigned n) { int sum=l, power=l; for (unsigned i,;,,O; i<=nø1; i++) { power *= 2; sum.+= power; J  / ｝ rturn·. sum; 将fl 中的int 都改为float, 可得到计算f(n)的另一个函数仅。假设unsigned 和int 型数据 都占32 位，float 采用IEEE 754 单精度标准。请回答下列问题。 (1)当n = O 时，fl 会出现死循环，为什么？若将fl 中的变量i 和n 都定义为int 型，则fl 是否还会出现死循环？为什么？ (2) fl(23)和:f2(23)的返回值是否相等？机器数各是什么（用十六进制表示）？ (3) fl(24)和:f2(24)的返回值分别为33 554 431 和33 554 432.0, 为什么不相等？ (4) f(31) = 232 -1, 而fl(31)的返回值却为-1, 为什么？若使fl(n)的返回值与f(n)相等，则 最大的n是多少？ (5) :f2(127)的机器数为7F80 OOOOH, 对应的值是什么？若使:f2(n)的结果不溢出，则最大 的n 是多少？若使:f2(n)的结果精确（无舍入），则最大的n 是多少？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2017 AND question_number=43);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2017, '计算机组成原理', '综合应用', 44, 'oo 分）在按字节编址的计算机M 上，题43 中fl 的部分源程序（阴影部分）与对应 的机器级代码（包括指令的虚拟地址）如下图所示。 int fl (unsign廿d n) 00401020 55 push ehp for(unsignecl i=O; i<= n -I; i++) 20 0040105E 39 4D F4 cmp rlword ptr l ehp-OCh] ,ecx 2017年计算机408统考真题 第 6 页，共 8 页 23 35 pown * = 2; 00401066 DI E2 return sum; 0040107F C3 sh! edx, I rel 其中，机器级代码行包括行号、虚拟地址、机器指令和汇编指令。请回答下列问题。 (1)计算机M是RISC还是CISC? 为什么？ (2) fl的机器指令代码共占多少字节？要求给出计算过程。 (3)第20条指令cmp通过i减n-1实现对i和n-1的比较。执行fl(O)过程中，当i=O时， cmp指令执行后，进／借位标志CF的内容是什么？要求给出计算过程。 (4)第23条指令shl通过左移操作实现了power*2运算，在f2中能否也用shl指令实现 power *2? 为什么？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2017 AND question_number=44);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2017, '操作系统', '综合应用', 45, '(7分）假定题44给出的计算机M采用二级分页虚拟存储管理方式，虚拟地址格 式如下： 页目录号(IO位） 页表索引(IO位） 页内偏移董(12位） 请针对题43的函数fl和题44中的机器指令代码，回答下列问题。 (1)函数fl的机器指令代码占多少页？ (2)取第1条指令(push ebp)时，若在进行地址变换的过程中需要访问内存中的页目录 和页表，则会分别访问它们各自的第几个表项（编号从0开始）？ (3) M的I/0采用中断控制方式。若进程P在调用fl之前通过scanf()获取n的值，则在执 行scanf()的过程中，进程P的状态会如何变化? CPU是否会进入内核态？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2017 AND question_number=45);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2017, '操作系统', '综合应用', 46, '(8分）某进程中有3个并发执行的线程threadl、thread2和thread3, 其伪代码如下 所示。 II复数的结构类型定义 thread! thread3 typedef slrucl I ! i cnum w: cnum w; float a; W = adu (X, y) ; w.a = l; float b; ... w,b= I; I cnum; ｝ z = add (z, w) ; (、num x, y, z; //全局变扯 y = add (y , w) ; thrcad2 ．．． II计算两个复数之和 '' ！ en um add (en um p, en um q) cnum w; I w = add(y,z); cnum s; ... s.a = p.a+q.a; ｝ s.b=p.b+q.b; return s; 2017年计算机408统考真题 第 7 页，共 8 页 请添加必要的信号量和P、V(或wait()、signal() 操作，要求确保线程互斥访问临界资源， 并且最大限度地并发执行。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2017 AND question_number=46);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2017, '计算机网络', '综合应用', 47, '(9分）甲乙双方均采用后退N帧协议(GBN)进行持续的双向数据传输，且双方始 终采用捎带确认，帧长均为1000B。SXJI和RXJI分别表示甲方和乙方发送的数据帧，其中x是发 送序号，y是确认序号（表示希望接收对方的下一帧序号）；数据帧的发送序号和确认序号字段 均为3比特。信道传输速率为lOOMbps , RTT = 0.96ms。下图给出了甲方发送数据帧和接收数 据帧的两种场景，其中t。为初始时刻，此时甲方的发送和确认序号均为O,t1时刻甲方有足够多 的数据待发送。 甲方 甲方 t。 lo t l 11 时间 时间 (a) (b) 请回答下列问题。 (1)对于图(a),t。时刻到t, 时刻期间，甲方可以断定乙方已正确接收的数据帧数是多少？ 正确接收的是哪几个帧？（请用SXJ'' 形式给出。） (2)对于图(a),从t, 时刻起，甲方在不出现超时且未收到乙方新的数据帧之前，最多还 可以发送多少个数据帧？其中第一个帧和最后一个帧分别是哪个？（请用SXJ'' 形式给出。） (3)对于图(b), 从t, 时刻起，甲方在不出现新的超时且未收到乙方新的数据帧之前，需 要重发多少个数据帧？重发的第一个帧是哪个？（请用SXJ'' 形式给出。） (4)甲方可以达到的最大信道利用率是多少？ 2017年计算机408统考真题 第 8 页，共 8 页', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2017 AND question_number=47);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '数据结构', '单选', 1, '设n 是描述问题规模的非负整数，下列程序段的时间复杂度是 。 x=0; while (n>=(x+1)*(x+1)) x=x+1;', '[{"key": "A", "text": "O(logn)"}, {"key": "B", "text": "O(n1/2)"}, {"key": "C", "text": "O(n)"}, {"key": "D", "text": "O(n2)"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=1);
