INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '数据结构', '单选', 8, '现有长度为11 且初始为空的散列表HT，散列函数是H(key) = key % 7，采用线性探查 （线性探测再散列）法解决冲突。将关键字序列87, 40, 30, 6, 11, 22, 98, 20 依次插入HT 后，HT 查找失败的平均查找长度是 。', '[{"key": "A", "text": "4"}, {"key": "B", "text": "5.25"}, {"key": "C", "text": "6"}, {"key": "D", "text": "6.299.设主串T = \"abaabaabcabaabc\"，模式串S = \"abaabc\"，采用KMP 算法进行模式匹配，到 匹配成功时为止，在匹配过程中进行的单个字符间的比较次数是 。"}, {"key": "A", "text": "9"}, {"key": "B", "text": "10"}, {"key": "C", "text": "12"}, {"key": "D", "text": "15"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=8);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '数据结构', '单选', 10, '排序过程中，对尚未确定最终位置的所有元素进行一遍处理称为一“趟”。下列序列 中，不．可能是快速排序第二趟结果的是 。', '[{"key": "A", "text": "5, 2, 16, 12, 28, 60, 32, 72"}, {"key": "B", "text": "2, 16, 5, 28, 12, 60, 32, 72"}, {"key": "C", "text": "2, 12, 16, 5, 28, 32, 72, 60"}, {"key": "D", "text": "5, 2, 12, 28, 16, 32, 72, 60"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=10);
