INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机组成原理', '单选', 14, '下列关于缺页处理的叙述中，错误的是 。', '[{"key": "A", "text": "缺页是在地址转换时CPU 检测到的一种异常"}, {"key": "B", "text": "缺页处理由操作系统提供的缺页处理程序来完成"}, {"key": "C", "text": "缺页处理程序根据页故障地址从外存读入所缺失的页"}, {"key": "D", "text": "缺页处理完成后回到发生缺页的指令的下一条指令执行"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=14);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机组成原理', '单选', 15, '某计算机采用大端方式，按字节编址。某指令中操作数的机器数为1234 FF00H，该操 作数采用基址寻址方式，形式地址（用补码表示）为FF12H，基址寄存器的内容为F000 0000H， 则该操作数的LSB（最低有效字节）所在的地址是 。', '[{"key": "A", "text": "F000 FF12H"}, {"key": "B", "text": "F000 FF15H"}, {"key": "C", "text": "EFFF FF12H"}, {"key": "D", "text": "EFFF FF15H"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=15);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机组成原理', '单选', 16, '下列有关处理器时钟脉冲信号的叙述中，错误的是 。', '[{"key": "A", "text": "时钟脉冲信号由机器脉冲源发出的脉冲信号经整形和分频后形成"}, {"key": "B", "text": "时钟脉冲信号的宽度称为时钟周期，时钟周期的倒数为机器主频"}, {"key": "C", "text": "时钟周期以相邻状态单元间组合逻辑电路的最大延迟为基准确定"}, {"key": "D", "text": "处理器总是在每来一个时钟脉冲信号时就开始执行一条新的指令"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=16);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机组成原理', '单选', 17, '某指令功能为R[r2]←R[r1] + M[R[r0]]，其两个源操作数分别采用寄存器、寄存器间接 寻址方式。对于下列给定部件，该指令在取数及执行过程中需要用到的是 。 I．通用寄存器组（GPRs） II．算术逻辑单元（ALU）', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=17);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机组成原理', '单选', 12, '下列关于冯·诺依曼结构计算机基本思想的叙述中，错误的是', '[{"key": "A", "text": "程序的功能都通过中央处理器执行指令实现"}, {"key": "B", "text": "指令和数据都用二进制数表示，形式上无差别"}, {"key": "C", "text": "指令按地址访问，数据都在指令中直接给出"}, {"key": "D", "text": "程序执行前，指令和数据需预先存放在存储器中"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=12);
