INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机组成原理', '单选', 18, '在采用“取指、译码/取数、执行、访存、写回”5 段流水线的处理器中，执行如下指 令序列，其中s0、s1、s2、s3 和t2 表示寄存器编号。 I1：add s2,s1,s0 //R[s2]R[s1]+R[s0] I2：load s3,0(t2) //R[s3]M[R[t2]+0] I3：add s2,s2,s3 //R[s2]R[s2]+R[s3] I4：store s2,0(t2) //M[R[t2]+0]R[s2] 下列指令对中，不存在数据冒险的是 。', '[{"key": "A", "text": "I1 和I3"}, {"key": "B", "text": "I2 和I3"}, {"key": "C", "text": "I2 和I4"}, {"key": "D", "text": "I3 和I4"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=18);
