INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机组成原理', '单选', 21, '某设备以中断方式与CPU 进行数据交换，CPU 主频为1GHz，设备接口中的数据缓冲 寄存器为32 位，设备的数据传输率为50kB/s。若每次中断开销（包括中断响应和中断处理）为 1000 个时钟周期，则CPU 用于该设备输入/输出的时间占整个CPU 时间的百分比最多是 。', '[{"key": "A", "text": "1.25%"}, {"key": "B", "text": "2.5%"}, {"key": "C", "text": "5%"}, {"key": "D", "text": "12.5%"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=21);
