INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '操作系统', '单选', 24, '下列选项中，可能会将进程唤醒的事件是 。 I．I/O 结束 II．某进程退出临界区 III．当前进程的时间片用完', '[{"key": "A", "text": "仅I"}, {"key": "B", "text": "仅III"}, {"key": "C", "text": "仅I、II"}, {"key": "D", "text": "I、II、III"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=24);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '操作系统', '单选', 25, '下列关于系统调用的叙述中，正确的是 。 I．在执行系统调用服务程序的过程中，CPU 处于内核态 II．操作系统通过提供系统调用避免用户程序直接访问外设 I．DMA 传送前由设备驱动程序设置传送参数 II．数据传送前由DMA 控制器请求总线使用权 III．数据传送由DMA 控制器直接控制总线完成 IV．DMA 传送结束后的处理由中断服务程序完成 III．不同的操作系统为应用程序提供了统一的系统调用接口 IV．系统调用是操作系统内核为应用程序提供服务的接口', '[{"key": "A", "text": "仅I、IV"}, {"key": "B", "text": "仅II、III"}, {"key": "C", "text": "仅I、II、IV"}, {"key": "D", "text": "仅I、III、IV"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=25);
