INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '操作系统', '单选', 27, '系统采用二级反馈队列调度算法进行进程调度。就绪队列Q1 采用时间片轮转调度算法， 时间片为10ms；就绪队列Q2 采用短进程优先调度算法；系统优先调度Q1 队列中的进程，当 Q1 为空时系统才会调度Q2 中的进程；新创建的进程首先进入Q1；Q1 中的进程执行一个时间片 后，若未结束，则转入Q2。若当前Q1、Q2 为空，系统依次创建进程P1、P2 后即开始进程调度， P1、P2 需要的CPU 时间分别为30ms 和20ms，则进程P1、P2 在系统中的平均等待时间为 。', '[{"key": "A", "text": "25ms"}, {"key": "B", "text": "20ms"}, {"key": "C", "text": "15ms"}, {"key": "D", "text": "10ms"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=27);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '操作系统', '单选', 28, '在分段存储管理系统中，用共享段表描述所有被共享的段。若进程P1 和P2 共享段S， 下列叙述中，错误的是 。', '[{"key": "A", "text": "在物理内存中仅保存一份段S 的内容"}, {"key": "B", "text": "段S 在P1 和P2 中应该具有相同的段号"}, {"key": "C", "text": "P1 和P2 共享段S 在共享段表中的段表项"}, {"key": "D", "text": "P1 和P2 都不再使用段S 时才回收段S 所占的内存空间"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=28);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '操作系统', '单选', 29, '某系统釆用LRU 页置换算法和局部置换策略，若系统为进程P 预分配了4 个页框， 进程P 访问页号的序列为0, 1, 2, 7, 0, 5, 3, 5, 0, 2, 7, 6，则进程访问上述页的过程中，产生页置 换的总次数是 。', '[{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6 。 I ．可以通过剥夺进程资源解除死锁 II．死锁的预防方法能确保系统不发生死锁 III．银行家算法可以判断系统是否处于死锁状态 IV．当系统出现死锁时，必然有两个或两个以上的进程处于阻塞态"}, {"key": "A", "text": "仅II、III"}, {"key": "B", "text": "仅I、II、IV"}, {"key": "C", "text": "仅I、II、III"}, {"key": "D", "text": "仅I、III、IV"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=29);
