INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '数据结构', '综合应用', 41, '（13 分）设线性表 1 2 3 2 1 ( , , , , , , ) n n n L a a a a a a     采用带头结点的单链表保存，链表中的 结点定义如下： typedef struct node { int data; struct node*next; } NODE； 请设计一个空间复杂度为O(1)且时间上尽可能高效的算法，重新排列L 中的各结点，得到 线性表 1 2 1 3 2 ( , , , , , , ) n n n L a a a a a a    。要求： （1）给出算法的基本设计思想。 （2）根据设计思想，采用C 或C++语言描述算法，关键之处给出注释。 （3）说明你所设计的算法的时间复杂度。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=41);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '数据结构', '综合应用', 42, '（10 分）请设计一个队列，要求满足：①初始时队列为空；②入队时，允许增加队列 占用空间；③出队后，出队元素所占用的空间可重复使用，即整个队列所占用的空间只增不减； ④入队操作和出队操作的时间复杂度始终保持为O(1)。请回答下列问题： （1）该队列是应选择链式存储结构，还是应选择顺序存储结构？ （2）画出队列的初始状态，并给出判断队空和队满的条件。 （3）画出第一个元素入队后的队列状态。 （4）给出入队操作和出队操作的基本过程。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=42);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机组成原理', '综合应用', 43, '（8 分）有n（n≥3）位哲学家围坐在一张圆桌边，每位哲学家交替地就餐和思考。在 圆桌中心有m（m≥1）个碗，每两位哲学家之间有一根筷子。每位哲学家必须取到一个碗和两 侧的筷子后，才能就餐，进餐完毕，将碗和筷子放回原位，并继续思考。为使尽可能多的哲学 家同时就餐，且防止出现死锁现象，请使用信号量的P、V 操作［wait()、signal()操作］描述上 述过程中的互斥与同步，并说明所用信号量及初值的含义。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=43);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机组成原理', '综合应用', 44, '（7 分）某计算机系统中的磁盘有300 个柱面，每个柱面有10 个磁道，每个磁道有200 个扇区，扇区大小为512B。文件系统的每个簇包含2 个扇区。请回答下列问题： 101 660 和110 560。若采用最短寻道时间优先（SSTF）调度算法，则系统访问簇的先后次序是 什么？ （3）第100 530 簇在磁盘上的物理地址是什么？将簇号转换成磁盘物理地址的过程是由I/O 系统的什么程序完成的？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=44);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '操作系统', '综合应用', 45, '（16 分）已知 ( ) ! ( 1) ( 2) 2 1 f n n n n n          ，计算f(n)的C 语言函数f1 的源程 序（阴影部分）及其在32 位计算机M 上的部分机器级代码如下： int f1(int n){ 1 00401000 55 push ebp … … … if(n>1) 1100401018 83 7D 08 01 cmp dword ptr [ebp+8],1 120040101C 7E 17 jle f1+35h (00401035) return n*f1(n-1); 130040101E 8B 45 08 mov eax, dword ptr [ebp+8] 1400401021 83 E8 01 sub eax, 1 1500401024 50 push eax 1600401025 E8 D6 FF FF FF call f1 ( 00401000) … … … 1900401030 0F AF C1 imul eax, ecx 2000401033 EB 05 jmp f1+3Ah (0040103a) （1）磁盘的容量是多少？ （2）假设磁头在85 号柱面上，此时有4 个磁盘访问请求，簇号分别为100 260、60 005、 else return 1; 2100401035 B8 01 00 00 00 mov eax,1 } … … … 2600401040 3B EC cmp ebp, esp … … … 300040104A C3 ret 其中，机器级代码行包括行号、虚拟地址、机器指令和汇编指令，计算机M 按字节编址，int 型数据占32 位。请回答下列问题： （1）计算f(10)需要调用函数f1 多少次？执行哪条指令会递归调用f1？ （2）上述代码中，哪条指令是条件转移指令？哪几条指令一定会使程序跳转执行？ （3）根据第16 行的call 指令，第17 行指令的虚拟地址应是多少？已知第16 行的call 指令 题47 图 采用相对寻址方式，该指令中的偏移量应是多少（给出计算过程）？已知第16 行的call 指令的 后4 字节为偏移量，M 是采用大端方式还是采用小端方式？ （4）f(13) = 6227020800，但f1(13)的返回值为1932053504，为什么两者不相等？要使 f1(13)能返回正确的结果，应如何修改f1 的源程序？ （5）第19 行的imul 指令（带符号整数乘）的功能是R[eax]←R[eax]×R[ecx]，当乘法器输 出的高、低32 位乘积之间满足什么条件时，溢出标志OF = 1？要使CPU 在发生溢出时转异常 处理，编译器应在imul 指令后应加一条什么指令？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=45);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '操作系统', '综合应用', 46, '（7 分）对于题45，若计算机M 的主存地址为32 位，釆用分页存储管理方式，页大小 为4KB，则第1 行的push 指令和第30 行的ret 指令是否在同一页中（说明理由）？若指令Cache 有64 行，采用4 路组相联映射方式，主存块大小为64B，则32 位主存地址中，哪几位表示块 内地址？哪几位表示Cache 组号？哪几位表示标记（tag）信息？读取第16 行的call 指令时， 只可能在指令Cache 的哪一组中命中（说明理由）？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=46);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2019, '计算机网络', '综合应用', 47, '（9 分）某网络拓扑如题47 图所示，其中R 为路由器，主机H1～H4 的IP 地址配置以 及R 的各接口IP 地址配置如图中所示。现有若干以太网交换机（无VLAN 功能）和路由器两 类网络互连设备可供选择。 请回答下列问题： （1）设备1、设备2 和设备3 分别应选择什么类型的网络设备？ （2）设备1、设备2 和设备3 中，哪几个设备的接口需要配置IP 地址？为对应的接口配置 正确的IP 地址。 （3）为确保主机H1～H4 能够访问Internet，R 需要提供什么服务？ （4）若主机H3 发送一个目的地址为192.168.1.127 的IP 数据报，网络中哪几个主机会接收 该数据报？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2019 AND question_number=47);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '数据结构', '单选', 1, '将一个10x10对称矩阵” 的上三角部分的元素叫力（1WZW/W10）按列优先存入C 语言的 一维数组N 中，元素加7,2在N 中的下标是（ ）。', '[{"key": "A", "text": "15"}, {"key": "B", "text": "16"}, {"key": "C", "text": "22"}, {"key": "D", "text": "23"}]', 'C', '上三角矩阵按列优先存储，先存储仅1 个元素的第一列，再存储有2 个元素的第二列，以', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=1);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '数据结构', '单选', 2, '对空栈 S 进行 Push 和 Pop 操作，入栈序列为 a, b, c, d, e , 经过 Push, Push, Pop, Push, Pop, Push, Push, Pop操作后得到的出栈序列是（ ）。', '[{"key": "A", "text": "b, a, c"}, {"key": "B", "text": "b, a, e"}, {"key": "C", "text": "b, c, a"}, {"key": "D", "text": "b, c, e"}]', 'D', '按题意，出入栈操作的过程如下：', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=2);
