INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '数据结构', '单选', 8, '若使用A O E 网估算工程进度，则下列叙述中正确的是（ ）o', '[{"key": "A", "text": "关键路径是从原点到汇点边数最多的一条路径"}, {"key": "B", "text": "关键路径是从原点到汇点路径长度最长的路径"}, {"key": "C", "text": "增加任一关键活动的时间不会延长工程的工期"}, {"key": "D", "text": "缩短任一关键活动的时间将会缩短工程的工期"}]', 'B', '关键路径是指权值之和最大而非边数最多的路径，故选项A 错误。选项B 正确，是关键路', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=8);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '数据结构', '单选', 9, '下列关于大根堆（至少含2 个元素）的叙述中，正确的是（ ）0 I . 可以将堆视为一棵完全二叉树 II.可以采用顺序存储方式保存堆 III.可以将堆视为一棵二叉排序树 I V . 堆中的次大值一定在根的下一层', '[{"key": "A", "text": "仅 I、II"}, {"key": "B", "text": "仅 II、in c . 仅 I、n 和 iv D. I、in 和 iv"}]', 'C', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=9);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '数据结构', '单选', 10, '依次将关键字5, 6, 9, 13, 8,2, 12, 15插入初始为空的4 阶B 树后，根结点中包含的关键字 是（ ）o', '[{"key": "A", "text": "8"}, {"key": "B", "text": "6,9"}, {"key": "C", "text": "8, 13"}, {"key": "D", "text": "9, 12"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=10);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '数据结构', '单选', 11, '对大部分元素已有序的数组进行排序时，直接插入排序比简单选择排序效率更高，其原因 是（ ）o I . 直接插入排序过程中元素之间的比较次数更少 II . 直接插入排序过程中所需要的辅助空间更少 III . 直接插入排序过程中元素的移动次数更少', '[{"key": "A", "text": "仅 I"}, {"key": "B", "text": "仅 ni c . 仅 I、II"}, {"key": "D", "text": "I、n 和 in"}]', 'A', '考虑较极端的情况，对于有序数组，直接插入排序的比较次数为〃- 1 , 简单选择排序的比', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=11);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 12, '下列给出的部件中，其位数（宽度）一定与机器字长相同的是（ ）o I. A L U II.指令寄存器 III.通用寄存器 I V . 浮点寄存器', '[{"key": "A", "text": "仅 I、II"}, {"key": "B", "text": "仅 I、ill c . 仅 II、ill"}, {"key": "D", "text": "仅 n 、in、iv"}]', 'B', '机器字长是指CPU内部用于整数运算的数据通路的宽度。CPU内部数据通路是指CPU内', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=12);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 13, '已知带符号整数用补码表示，float型数据用IEEE 754标准表示，假定变量x 的类型只可能 是int或float,当x 的机器数为C800 0000H时，x 的值可能是（ ）。', '[{"key": "A", "text": "-7x227"}, {"key": "B", "text": "-216"}, {"key": "C", "text": "217"}, {"key": "D", "text": "25x227"}]', 'A', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=13);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 14, '在按字节编址，采用小端方式的3 2 位计算机中，按边界对齐方式为以下C 语言结构型变 量a 分配存储空间： Struct record{ short xl; int x2; } a; 若a 的首地址为2020 FE00H, a 的成员变量x 2 的机器数为1234 0 0 0 0 H ,则其中3 4 H 所在 存储单元的地址是（ ）。 ・ 022 •', '[{"key": "A", "text": "2020 FE03H"}, {"key": "B", "text": "2020 FE04H"}, {"key": "C", "text": "2020 FE05H"}, {"key": "D", "text": "2020 FE06H"}]', 'D', '在3 2 位计算机中，按字节编址，根据小端方式和按边界对齐的定义，给出变量a 的存放方', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=14);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 15, '下列关于TLB和Cache的叙述中，错误的是（ ）。', '[{"key": "A", "text": "命中率都与程序局部性有关"}, {"key": "B", "text": "缺失后都需要去访问主存"}, {"key": "C", "text": "缺失处理都可以由硬件实现"}, {"key": "D", "text": "都由DRAM存储器组成"}]', 'D', 'Cache由SRAM组成；TLB通常由相联存储器组成，也可由SRAM组成。DRAM需要不', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=15);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 16, '某计算机采用16位定长指令字格式，操作码位数和寻址方式位数固定，指令系统有4 8 条 指令，支持直接、间接、立即、相对4 种寻址方式。单地址指令中，直接寻址方式的可寻 址范围是（ ）o', '[{"key": "A", "text": "0—255"}, {"key": "B", "text": "0-1023"}, {"key": "C", "text": "-128-127"}, {"key": "D", "text": "—512〜511"}]', 'A', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=16);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 17, '下列给出的处理器类型中，理想情况下，CPI为1 的是（ ）。 I . 单周期CPU I I . 多周期CPU I I I . 基本流水线CPU I V .超标量流水线CPU', '[{"key": "A", "text": "仅 I、II"}, {"key": "B", "text": "仅 I、III"}, {"key": "C", "text": "仅 II、IV"}, {"key": "D", "text": "仅 n i、IV"}]', 'B', 'CPI表示执行指令所需的时钟周期数。对于一个程序或一台机器来说，其CPI指执行该程', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=17);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 18, '下列关于“自陷”（T ra p ,也称陷阱）的叙述中，错误的是（ ）。', '[{"key": "A", "text": "自陷是通过陷阱指令预先设定的一类外部中断事件"}, {"key": "B", "text": "自陷可用于实现程序调试时的断点设置和单步跟踪"}, {"key": "C", "text": "自陷发生后CPU将转去执行操作系统内核相应程序"}, {"key": "D", "text": "自陷处理完成后返回到陷阱指令的下一条指令执行"}]', 'A', '自陷是一种内部异常，A 错误。在80x86中，用于程序调试的“断点设置”功能是通过“自', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=18);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 19, 'Q P I总线是一种点对点全工同步串行总线，总线上的设备可同时接收和发送信息，每个方 向可同时传输20位信息（16位数据+4位校验位），每个QPI数据包有80位信息，分2 个 时钟周期传送，每个时钟周期传递2 次。因此，Q P I总线带宽为：每秒传送次数x2Bx2。 若QPI时钟频率为2.4G H z,则总线带宽为（ ）o', '[{"key": "A", "text": "4.8GBps"}, {"key": "B", "text": "9.6GBps"}, {"key": "C", "text": "19.2GBps"}, {"key": "D", "text": "38.4GBps"}]', 'C', '每个时钟周期传送2 次，故每秒传送的次数= 时钟频率x2 = 2.4Gx2/s。', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=19);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 20, '下列事件中，属于外部中断事件的是（ ）o i . 访存时缺页 I I . 定时器到时 i n . 网络数据包到达', '[{"key": "A", "text": "仅 I、II"}, {"key": "B", "text": "仅 I、HI c . 仅 n 、iii"}, {"key": "D", "text": "I、n 和 ni"}]', 'C', '访存时缺页属于内部异常，I 错误；定时器到时描述的是时钟中断，属于外部中断，I I 正确；', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=20);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 21, '外部中断包括不可屏蔽中断（NMI）和可屏蔽中断，下列关于外部中断的叙述中，错误的 是（ ）。', '[{"key": "A", "text": "C P U 处于关中断状态时，也能响应NMI请求"}, {"key": "B", "text": "一旦可屏蔽中断请求信号有效，CPU将立即响应"}, {"key": "C", "text": "不可屏蔽中断的优先级比可屏蔽中断的优先级高"}, {"key": "D", "text": "可通过中断屏蔽字改变可屏蔽中断的处理优先级"}]', 'B', '由CPU内部产生的异常称为内中断，内中断都是不可屏蔽中断。通过中断请求线INTR和，', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=21);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '单选', 22, '若设备采用周期挪用DMA方式进行输入和输出，每次DMA传送的数据块大小为5 1 2 字 节，相应的I/O接口中有一个32位数数据缓冲寄存器。对于数据输入过程，下列叙述中， 错误的是（ ）o ・023・', '[{"key": "A", "text": "每准备好32位数据，DMA控制器就发出一次总线请求"}, {"key": "B", "text": "相对于CPU, DMA控制器的总线使用权的优先级更高"}, {"key": "C", "text": "在整个数据块的传送过程中，CPU不可以访问主存储器"}, {"key": "D", "text": "数据块传送结束时，会产生“DMA传送结束”中断请求"}]', 'C', '周期挪用法由DMA控制器挪用一个或几个主存周期来访问主存，传送完一个数据字后立', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=22);
