INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机网络', '单选', 36, '假设主机甲采用停-等协议向主机乙发送数据帧，数据帧长与确认帧长均为1000B,数据传 输速率是10kbps,单项传播延时是200ms。则甲的最大信道利用率为（ ）。', '[{"key": "A", "text": "80%"}, {"key": "B", "text": "66.7%"}, {"key": "C", "text": "44.4%"}, {"key": "D", "text": "40%"}]', 'D', '发送数据帧和确认帧的时间均为t= 1000x8b/10kbps = 800mso', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=36);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机网络', '单选', 37, '某IEEE 802.11无线局域网中，主机H 与A P之间发送或接收CSMA/CA帧的过程如下图 所示。在H 或A P发送帧前所等待的帧间间隔时间（IFS）中，最长的是（ ）0', '[{"key": "A", "text": "IFS1"}, {"key": "B", "text": "IFS2"}, {"key": "C", "text": "IFS3"}, {"key": "D", "text": "IFS4"}]', 'A', '为了尽量避免碰撞，802.11规定，所有站在完成发送后，必须等待一段很短的时间（继续', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=37);
