INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机网络', '单选', 39, '若主机甲与主机乙建立TCP连接时，发送的SYN段中的序号为1 0 00 ,在断开连接时，甲 发送给乙的FIN段中的序号为5001,则在无任何重传的情况下，甲向乙已经发送的应用层 数据的字节数为（ ）o • 026 •', '[{"key": "A", "text": "4002"}, {"key": "B", "text": "4001"}, {"key": "C", "text": "4000"}, {"key": "D", "text": "3999"}]', 'C', '甲与乙建立TCP连接时发送的SYN段中的序号为1000,则在数据传输阶段所用的起始序', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=39);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机网络', '单选', 40, '假设下图所示网络中的本地域名服务器只提供递归查询服务，其他域名服务器均只提供迭 代查询服务；局域网内主机访问Internet上各服务器的往返时间（RTT）均为10m s,忽略 其他各种时延。若主机H 通过超链接http://www.abc.com/index.html请求浏览纯文本Web 页index.html,则从点击超链接开始到浏览器接收到index.html页面为止，所需的最短时间 与最长时间分别是（ ）。 二、综合应用题 第41〜47 小题，共70分。', NULL, 'D', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=40);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '数据结构', '综合应用', 41, '（13分）定义三元组3 ,6 , c）（其中4 瓦c 均为正数）的距离。=|々—臼+归―c| + |c —臼。给 定3 个非空整数集合S 、& 和用，按升序分别存储在3 个数组中。设计一个尽可能高效的 算法，计算并输出所有可能的三元组S " , C ）（4 G S I" £ S 2 , C £ S 3 ）中的最小距离。例如& = {-1,0,9）, 52 ={-25,-10, 10, 11}, S3 ={2,9, 17,30,41},则最小距离为 2 , 相应的三元组为 （9, 10, 9） o 要求： 1）给出算法的基本设计思想。 2）根据设计思想，采用C 或C++语言描述算法，关键之处给出注释。 3）说明你所设计算法的时间复杂度和空间复杂度。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=41);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '数据结构', '综合应用', 42, '（1 0 分）若任一个字符的编码都不是其他字符编码的前缀，则称这种编码具有前缀特性。 现有某字符集（字符个数2 2 ）的不等长编码，每个字符的编码均为二进制的0、1 序列， 最长为上位，且具有前缀特性。请回答下列问题： 1）哪种数据结构适宜保存上述具有前缀特性的不等长编码？ 2）基于你所设计的数据结构，简述从0/1串到字符串的译码过程。 3）简述判定某字符集的不等长编码是否具有前缀特性的过程。', NULL, '', '1 )使用一棵二叉树保存字符集中各字符的编码，每个编码对应于从根开始到达某叶结点的', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=42);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '综合应用', 43, '（13分）有实现xxy的两个C 语言函数如下： unsigned umul （unsigned x, unsigned y） { return x*y; } int imul （int x, int y） {return x * y; } 假定某计算机M 中ALU只能进行加减运算和逻辑运算。请回答下列问题。 ・027・ 1）若M 的指令系统中没有乘法指令，但有加法、减法和位移等指令，则在M 上也能实现 上述两个函数中的乘法运算，为什么？ 2）若M 的指令系统中有乘法指令，则基于ALU、位移器、寄存器以及相应控制逻辑实现 乘法指令时，控制逻辑的作用是什么？ 3）针对以下三种情况：①没有乘法指令；②有使用ALU和位移器实现的乘法指令； ③有使用阵列乘法器实现的乘法指令，函数umul（）在哪种情况下执行时间最长？哪种 情况下执行的时间最短？说明理由 4 ） z 位整数乘法指令可保存2〃位乘积，当仅取低〃位作为乘积时，其结果可能会发生溢 出。当〃 = 32,x = 2 3 i-l,y = 2 时，带符号整数乘法指令和无符号整数乘法指令得到的 xxy的2〃位乘积分别是什么（用十六进制表示）？此时函数umul（）和imul（）的返回结 果是否溢出？对于无符号整数乘法运算，当仅取乘积的低甩位作为乘法结果时，如何 用2勿位乘积进行溢出判断？', NULL, '', '1）乘法运算可以通过加法和移位来实现。编译器可以将乘法运算转换为一个循环代码段，', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=43);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机组成原理', '综合应用', 44, '（10分）假定主存地址为32位，按字节编址，指令Cache和数据Cache与主存之间均采用 8 路组相联映射方式，直写（Write Through）写策略和LRU替换算法，主存块大小为64B, 数据区容量各为32KB。开始时Cache均为空。请回答下列问题。 1） Cache每一行中标记（Tag）、LRU位各占几位？是否有修改位？ 2）有如下C 语言程序段： for （k = 0; k < 1024 ; k++） s[k] = 2 * s[k]; 若数组s 及其变量k 均为in t型，int型数据占4 B ,变量k 分配在寄存器中，数组s 在 主存中的起始地址为0080 00C 0H ,则该程序段执行过程中，访问数组s 的数据Cache 缺失次数为多少？ 3）若CPU最先开始的访问操作是读取主存单元0001 0003H中的指令，简要说明从Cache 中访问该指令的过程，包括Cache缺失处理过程。', NULL, '', '1）主存块大小为64B = 26字节，所以主存地址低6 位为块内地址，C ache组数为', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=44);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '操作系统', '综合应用', 45, '（7 分）现有5 个操作A、B、C、D 和E , 操作C 必须在A 和B 完成后执行，操作E 必须 在C 和D 完成后执行，请使用信号量的wait。、signal。操作（P、V 操作）描述上述操作 之间的同步关系，并说明所用信号量及其初值。', NULL, '', '本题要求实现操作的先后顺序，没有互斥关系，是一个简单的同步问题。', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=45);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '操作系统', '综合应用', 46, '（8 分）某3 2 位系统采用基于二级页表的请求分页存储管理方式，按字节编址，页目录项 和页表项长度均为4 字节，虚拟地址结构如下所示。 页目录号（10位） 页号（10位） 页内偏移量（12位） 某C 程序中数组a[1024][1024]的起始虚拟地址为1080 0000H,数组元素占4 字节，该程序 运行时，其进程的页目录起始物理地址为0020 1000H ,请回答下列问题。 1）数组元素的虚拟地址是什么？对应的页目录号和页号分别是什么？对应的页 目录项的物理地址是什么？若该目录项中存放的页框号为00301H ,则所在 页 对应的页表项的物理地址是什么？ 2）数组a 在虚拟地址空间中所占的区域是否必须连续？在物理地址空间中所占区域是否 必须连续？ • 028 - 3）已知数组a 按行优先方式存放，若对数组a 分别按行遍历和按列遍历，则哪种遍历方式 的局部性更好？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=46);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2020, '计算机网络', '综合应用', 47, '（9 分）某校园网有两个局域网，通过路由器R I、R 2和R 3互联后接入Internet, S1和S2 为以太网交换机。局域网采用静态IP 地址配置，路由器部分接口以及各主机的IP 地址如 下图所示。 192.168.1,2 192.168.1,3 192.168.1.2 192.168.1.3 假设NAT转换表结构为 外网 内网 IP 地址 端口号 IP 地址 端口号 请回答下列问题： 1）为使H 2和H 3能够访问Web服务器（使用默认端口号），需要进行什么配置？ 2）若H 2主动访问Web服务器时，将HTTP请求报文封装到IP 数据报P 中发送，则H2 发送P 的源IP 地址和目的IP 地址分别是什么？经过R 3转发后，P 的源IP 地址和目的 IP 地址分别是什么？经过R 2转发后，P 的源IP 地址和目的IP 地址分别是什么？ • 029 -', NULL, '', '1）两个子网使用了相同的网段，且路由器开启了 NAT功能，加上题干给出了 NAT表的结', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2020 AND question_number=47);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '数据结构', '单选', 1, '已知头指针h 指向一个带头结点的非空单循环链表，结点结构为 data next 其中next是指向直接后继结点的指针，P 是尾指针，q 是临时指针。现要删除该链表的第 一个元素，正确的语句序列是( )o', '[{"key": "A", "text": "h -> next = h -> next -> next; q = h-> next; free(q);"}, {"key": "B", "text": "q = h -> next; h -> next = h -> next -> next; free(q);"}, {"key": "C", "text": "q = h-> next; h -> next = q -> next; if(p != q)p = h; free(q);"}, {"key": "D", "text": "q = h-> next; h -> next = q-> next; if(p == q)p = h; free(q);"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=1);
