INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机组成原理', '单选', 22, '下列是关于多重中断系统中CPU响应中断的叙述，其中错误的是（ ）o', '[{"key": "A", "text": "仅在用户态（执行用户程序）下，CPU才能检测和响应中断"}, {"key": "B", "text": "CPU只有在检测到中断请求信号后，才会进入中断响应周期"}, {"key": "C", "text": "进入中断响应周期时，CPU一定处于中断允许（开中断）状态"}, {"key": "D", "text": "若CPU检测到中断请求信号，则一定存在未被屏蔽的中断源请求信号"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=22);
