INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '操作系统', '单选', 26, '某系统中磁盘的磁道数为200 （0 -1 9 9 ）, 磁头当前在184号磁道上。用户进程提出的磁盘 访问请求对应的磁道号依次为184, 187, 176, 182, 199。若采用最短寻道时间优先调度算法 （SSTF）完成磁盘访问，则磁头移动的距离（磁道数）是（ ）o', '[{"key": "A", "text": "37"}, {"key": "B", "text": "38"}, {"key": "C", "text": "41"}, {"key": "D", "text": "42"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=26);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '操作系统', '单选', 27, '下列事件中，可能引起进程调度程序执行的是（ ）o I . 中断处理结束I I . 进程阻塞 i n . 进程执行结束 i v . 进程的时间片用完', '[{"key": "A", "text": "仅 I、III"}, {"key": "B", "text": "仅 II、IV"}, {"key": "C", "text": "仅皿、IV"}, {"key": "D", "text": "I、n 、in 和 IV"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=27);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '操作系统', '单选', 28, '某请求分页存储系统的页大小为4 K B ,按字节编址。系统给进程P 分配2 个固定的页框, 并采用改进型Clock置换算法，进程P 页表的部分内容如下表所示。 页框号 存在位 1：存在，0 : 不存在 访问位 1：访问，0 : 未访问 修改位 1：修改，0 : 未修改 20 H 0 0 0 60 H 1 1 0 80 H 1 1 1 若P 访问虚拟地址为02A01H的存储单元，则经地址变换后得到的物理地址是（ ）0', '[{"key": "A", "text": "00A01H"}, {"key": "B", "text": "20A01H"}, {"key": "C", "text": "60A01H"}, {"key": "D", "text": "80A01H"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=28);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '操作系统', '单选', 29, '在采用二级页表的分页系统中，CPU页表基址寄存器中的内容是（ ）。', '[{"key": "A", "text": "当前进程的一级页表的起始虚拟地址 • 004 • 2021年计算机408统考真题 第 4 页，共 9 页"}, {"key": "B", "text": "当前进程的一级页表的起始物理地址"}, {"key": "C", "text": "当前进程的二级页表的起始虚拟地址"}, {"key": "D", "text": "当前进程的二级页表的起始物理地址"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=29);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '操作系统', '单选', 30, '若目录dir下有文件f il e l,则为删除该文件内核不必完成的工作是（ ） o', '[{"key": "A", "text": "删除file l的快捷方式"}, {"key": "B", "text": "释放file l的文件控制块"}, {"key": "C", "text": "释放file l占用的磁盘空间"}, {"key": "D", "text": "删除目录dir中与filel对应的目录项"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=30);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '操作系统', '单选', 31, '若系统中有〃（〃2 2 ）个进程，每个进程均需要使用某类临界资源2 个，则系统不会发生 死锁所需的该类资源总数至少是（ )o', '[{"key": "A", "text": "2"}, {"key": "B", "text": "n"}, {"key": "C", "text": "〃 + 1"}, {"key": "D", "text": "2n"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=31);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '操作系统', '单选', 32, '下列选项中，通过系统调用完成的操作是（ ）o', '[{"key": "A", "text": "页置换"}, {"key": "B", "text": "进程调度"}, {"key": "C", "text": "创建新进程"}, {"key": "D", "text": "生成随机整数"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=32);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机网络', '单选', 33, '在TCP/IP参考模型中，由传输层相邻的下一层实现的主要功能是（ ）。', '[{"key": "A", "text": "对话管理"}, {"key": "B", "text": "路由选择"}, {"key": "C", "text": "端到端报文段传输"}, {"key": "D", "text": "结点到结点流量控制 若下图为一段差分曼彻斯特编码信号波形，则其编码的二进制位串是（ ）"}, {"key": "A", "text": "1011 1001"}, {"key": "B", "text": "1101 0001"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=33);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机网络', '单选', 35, '现将一个IP 网络划分为3 个子网, 不可能是另外两个子网之一的是（', '[{"key": "A", "text": "192.168.9.0/25"}, {"key": "C", "text": "192.168.9.192/26"}, {"key": "C", "text": "0010 1110"}, {"key": "D", "text": "1011 0110 若其中一个子网是192.168.9.128/26,则下列网络中, ) O"}, {"key": "B", "text": "192.168.9.0/26"}, {"key": "D", "text": "192.168.9.192/27"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=35);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机网络', '单选', 36, '若路由器向MTU = 800B的链路转发一个总长度为1580B的IP数据报（首部长度为20B） 时，进行了分片，且每个分片尽可能大，则第2 个分片的总长度字段和MF标志位的值分 别是（ ）o', '[{"key": "A", "text": "796,0"}, {"key": "B", "text": "796, 1"}, {"key": "C", "text": "800,0"}, {"key": "D", "text": "800, 1"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=36);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机网络', '单选', 37, '某网络中的所有路由器均采用距离向量路由算法计算路由。若路由器E 与邻居路由器A,B, C 和D 之间的直接链路距离分别是8, 10, 12和6 , 且E 收到邻居路由器的距离向量如下表 所示，则路由器E 更新后的到达目的网络Netl〜Net4的距离分别是（ ）。 ・ 005 • 2021年计算机408统考真题 第 5 页，共 9 页 目的网络 A 的距离向量 B 的距离向量 C 的距离向量 D 的距离向量 1 23 20 22 12 35 30 28 24 18 16 36 36 30 8 24', '[{"key": "A", "text": "9, 10, 12, 6"}, {"key": "B", "text": "9, 10, 28, 20"}, {"key": "C", "text": "9, 20, 12, 20"}, {"key": "D", "text": "9,20,28,20"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=37);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机网络', '单选', 38, '若客户首先向服务器发送FIN 段请求断开TCP连接，则当客户收到服务器发送的FIN 段并 向服务器发送了 ACK段后，客户的TCP状态转换为（ ）。', '[{"key": "A", "text": "CLOSE_WAIT"}, {"key": "B", "text": "TIME_WAIT"}, {"key": "C", "text": "FIN_WAIT_1"}, {"key": "D", "text": "FIN_WAIT_2"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=38);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机网络', '单选', 39, '若大小为12B的应用层数据分别通过1 个UDP数据报和1 个TCP段传输，则该UDP数据 报和TCP段实现的有效载荷（应用层数据）最大传输效率分别是（ ）。', '[{"key": "A", "text": "37.5%, 16.7%"}, {"key": "B", "text": "37.5%, 37.5%"}, {"key": "C", "text": "60.0%, 16.7%"}, {"key": "D", "text": "60.0%, 37.5%"}]', '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=39);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机网络', '单选', 40, '设主机甲通过TC P向主机乙发送数据，部分过程如下图所示。甲在而时刻发送一个序号seq = 501、封装200B数据的段，在4 时刻收到乙发送的序号seq = 601、确认序号ack_seq = 501、 接收窗口 rcvwnd = 500B的段，则甲在未收到新的确认段之前，可以继续向乙发送的数据序号 范围是（ ）。 二、综合应用题 第41〜47小题，共70分。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=40);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '数据结构', '综合应用', 41, '（15分）已知无向连通图G 由顶点集P 和边集E 组成，|^| > 0 , 当G 中度为奇数的顶点个 数为不大于2 的偶数时，G 存在包含所有边且长度为区|的路径（称为E L 路径）。设图G 采用邻接矩阵存储，类型定义如下： typedef struct{ //图的定义 int numVertices,numEdges; //图中实际的顶点数和边数 char VerticesList[MAXV]; //顶点表。MAXV为已定义常量 int Edge[MAXV][MAXV]； ・ 006 ・ 2021年计算机408统考真题 第 6 页，共 9 页 //邻接矩阵 }MGraph; 请设计算法i n t IsExistEL(M G raph G ), 判断G 是否存在E L 路径，若存在，则返回 1 , 否则返回0。要求： 1 ) 给出算法的基本设计思想。 2 ) 根据设计思想，采用C 或C++语言描述算法，关键之处给出注释。 3 ) 说明你所设计算法的时间复杂度和空间复杂度。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=41);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '数据结构', '综合应用', 42, '( 8 分)已知某排序算法如下： void cmpCountSort(int a [],int b [],int n) { int i,j,*count; count=(int *)malloc(sizeof(int)*n); //C++语言：count=new int [n]; for(i=0;i<n;i++) count[i]=0; for(i=0;i<n-l;i++) for(j=i + l;j <n;j ++) if(a[i]<a[j]) count[j]++; else count[i]++; for(i=0;i<n;i++) b[count[i]]= a [i]; free (count) ; //C++语言：delete count; ) 请回答下列问题。 1 ) 若有 in t a [ ] = { 2 5 ,-1 0 z 2 5 ,1 0 z l l z 1 9 } , b [ 6 ] 则调用 cmpCountSort (a, b, 6) 后数组b 中的内容是什么？ 2 ) 若a 中含有〃个元素，则算法执行过程中，元素之间的比较次数是多少？ 3 ) 该算法是稳定的吗？若是，则阐述理由；否则，修改为稳定排序算法。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=42);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机组成原理', '综合应用', 43, '(15 分)假定计算机M 字长为16位，按字节编址，连接CPU和主存的系统总线中地址线 为20位、数据线为8 位，采用16位定长指令字，指令格式及其说明如下： 格式 6 位 2 位 2 位 2 位 4 位 指令功能或指令类型说明 R 型 000000 rs Ft rd opl R[rd] - R[rs] opl R[rt] I 型 op2 rs rt imm 含ALU运算、条件转移和访存 操作3类指令 J 型 op3 target PC 的低 10 位— target 其中，opl〜op3为操作码，rs, r t和rd 为通用寄存器编号，R[r]表示寄存器i•的内容，imm 为立即数，target为转移目标的形式地址。请回答下列问题。 1) A L U 的宽度是多少位？可寻址主存空间大小为多少字节？指令寄存器、主存地址寄存 器( M A R )和主存数据寄存器( M D R )分别应有多少位？ 2) R 型格式最多可定义多少种操作？ I 型和J 型格式总共最多可定义多少种操作？通用寄 • 007 • 2021年计算机408统考真题 第 7 页，共 9 页 存器最多有多少个？ 3）假定o p l为0010和0011时，分别表示带符号整数减法和带符号整数乘法指令，则指令 01B2H的功能是什么（参考上述指令功能说明的格式进行描述）？若1, 2, 3 号通用寄 存器当前内容分别为B052H, 0008H, 0020H ,则分别执行指令01B2H和01B3H后，3 号通用寄存器内容各是什么？各自结果是否溢出？ 4）若采用I 型格式的访存指令中imm （偏移量）为带符号整数，则地址计算时应对imm 进行零扩展还是符号扩展？ 5）无条件转移指令可以采用上述哪种指令格式？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=43);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '计算机组成原理', '综合应用', 44, '（8 分）假设计算机M 的主存地址为2 4 位，按字节编址；采用分页存储管理方式，虚拟 地址为30位，页大小为4 KB； TLB采用2 路组相联方式和LRU替换策略，共8 组。请回 答下列问题。 1）虚拟地址中哪几位表示虚页号？哪几位表示页内地址？ 2）已知访问TLB时虚页号高位部分用作TLB标记，低位部分用作TLB组号，M 的虚拟 地址中哪几位是TLB标记？哪几位是TLB组号？ 3）假设TLB初始时为空，访问的虚页号依次为10, 12, 16,7,26,4, 12和2 0 , 在此过程中， 哪一个虚页号对应的TLB表项被替换？说明理由。 4）若将M 中的虚拟地址位数增加到32位，则TLB表项的位数增加几位？', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=44);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2021, '操作系统', '综合应用', 45, '（7 分）下表给出了整型信号量S 的w a it （）和s i g n a l 。操作的功能描述，以及采用开/ 关中断指令实现信号量操作互斥的两种方法。 功能描述 方法1 方法2 Semaphore S; Semaphore S; Semaphore S; wait(S){ wait (S){ wait (S){ while(S<=0); 关中断； 关中断； S=S-1; while(S<=0); while(S<=0); ) S=S-1; 开中断； 开中断； I 关中断； i J S=S-1; 开中断； signal(S){ signal (S){ J signal(S){ S=S+1; 关中断； 关中断； ) S=S+1; S=S+1; 开中断； ） 开中断； ） 请回答下列问题。 1）为什么在w a it （）和s i g n a l 。操作中对信号量S 的访问必须互斥执行？ 2）分别说明方法1 和方法2 是否正确。若不正确，请说明理由。 3）用户程序能否使用开/关中断指令实现临界区互斥？为什么？ • 008 - 2021年计算机408统考真题 第 8 页，共 9 页', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2021 AND question_number=45);
