INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '数据结构', '单选', 1, '答题前，考生在试题册指定位置上填写考生编号和考生姓名；在答题卡指定位置上填写报 考单位、考生姓名和考生编号，并涂写考生编号信息点。', NULL, 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=1);
