INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '数据结构', '单选', 3, '选择题的答案必须涂写在答题卡和相应题号的选项上,非选择题的答案必须书写在答题卡 指定位置的边框区城内，超出答题区域书写的答案无效；在草稿纸、试题册上答题无效。', NULL, 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=3);
