INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '计算机网络', '单选', 38, '假设主机甲和主机乙已建立一个TCP连接，最大段长MSS = 1 K B ,甲一直有数据向乙发送, 当甲的拥塞窗口为16K B 时，计时器发生了超时，则甲的拥塞窗口再次增长到16K B所需要 的时间至少是（ ）o', '[{"key": "A", "text": "4RTT"}, {"key": "B", "text": "5RTT"}, {"key": "C", "text": "11 RTT"}, {"key": "D", "text": "16RTT"}]', 'C', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=38);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '计算机网络', '单选', 39, '假设客户C 和服务器S 已建立一个TCP连接，通信往返时间RTT = 50 m s , 最长报文段寿命 MSL = 8 0 0 m s ,数据传输结束后，C 主动请求断开连接。若从C 主动向S 发出FIN段时刻算 起，则。和S 进入CLOSED状态所需的时间至少分别是（ 工', '[{"key": "A", "text": "850 ms, 50 ms"}, {"key": "B", "text": "1650 ms, 50 ms"}, {"key": "C", "text": "850 ms, 75 ms"}, {"key": "D", "text": "1650 ms, 75 ms"}]', 'D', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=39);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '计算机网络', '单选', 40, '假设主机H 通过HTTP/1.1请求浏览某W eb服务器S 上的W eb页news408.htal, news408.html 第5 页（共8 页） 引用了同目录下的1 幅图像，news408.html文件大小为1 MSS （最大段长），图像文件大小为 3 MSS, H 访问S 的往返时间RTT = 10 m s ,忽略HTTP响应报文的首部开销和TCP段传输时 延。若H 已完成域名解析，则从H 请求与S 建立TC P连接时刻起，到接收到全部内容止， 所需的时间至少是（ ）o', '[{"key": "A", "text": "30 ms"}, {"key": "B", "text": "40 ms"}, {"key": "C", "text": "50 ms"}, {"key": "D", "text": "60 ms 二、综合应用题：41〜4 7 小题，共7 0 分。 4L （13分）已知非空二叉树T 的结点值均为正整数，采用顺序存储方式保存，数据结构定义如下: type def struct { // MAX_S 工 ZE 为已定义常量 int SqBiTNode[MAX_SIZE]; 〃保存二叉树结点值的数组 int ElemNum; . 一 / / 实际占用的数组元素个数 } SqBiTree; '' T 市示后茬的结舌茬薪组SqBiTNode.申角二T袤奈。祠如…对于下函所示的的裸菲生二攵留 T1 和 T2, 请设计一个尽可能高效的算法，判定一棵采用这种方式存储的二叉树是否为二叉搜索树，若 是，则返回tr u e ,否则，返回false。要求： 1）给出算法的基本设计思想。 2 ）根据设计思想，采用C 或C++语言描述算法，关键之处给出注释。"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=40);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '数据结构', '综合应用', 42, '（10分）现有〃（« > 100000）个数保存在一维数组M 中，需要查找M 中最小的10个数。请 回答下列问题。 1）设计一个完成上述查找任务的算法，要求平均情况下的比较次数尽可能少，简述其算法思 想（不需要程序实现）。 2）说明你所设计的算法平均情况下的时间复杂度和空间复杂度。', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=42);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '计算机组成原理', '综合应用', 43, '（1 5 分）某C P U 中部分数据通路如题4 3 图所示，其中，GPRs为通用寄存器组；F R 为标志 寄存器，用于存放ALU产生的标志信息；带箭头虚线表示控制信号，如控制信号Read、Write 分别表示主存读、主存写，MDRin表示内部总线上数据写入MDR, MDRout表示M DR的内 容送内部总线。 第6 贝（共8 贝） 题4 3 图 请回答下列问题。 1＞设ALU的输入端A、B 及输出端F 的最高位分别为A . B n及及5, F R 中的符号标志和 溢出标志分别为SF和O F ,则S F 的逻辑表达式是什么？ A 加B、A 减B 时O F 的逻辑表 达式分别是什么？要求逻辑表达式的输入变量为A s B15及F15。 2）为什么要设置暂存器丫和Z? 3）若GPRs的输入端rs、rd 分别为所读、写的通用寄存器的编号，则GPRs中最多有多少个 通用寄存器？ rs和： rd来自图中的哪个寄存器？已知GPRs内部有一个地址译码器和一个多 路选择器，rd 应连接地址译码器还是多路选择器？ 4）取指令阶段（不考虑PC 增量操作）的控制信号序列是什么？若从发出主存读命令到主存 读出数据并传送到MDR共需5 个时钟周期，则取指令阶段至少需要几个时钟周期？ 5）图中控制信号由什么部件产生？图中哪些寄存器的输出信号会连到该部件的输入端？', NULL, '', '1）符号标志SF.表示运算结果的正负性，因此SF = Fi5。', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=43);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '计算机组成原理', '综合应用', 44, '（8 分）假设某磁盘驱动器中有4 个双面盘片,每个盘面有20000个磁道，每个磁道有500个 扇区，每个扇区可记录512字节的数据,盘片转速为7200 RPM（转/分）,平均寻道时间为5 ms。 请回答下列问题° 1）每个扇区包含数据及其地址信息，地址信息分为3 个字段。这3 个字段的名称各是什么？ 对于该磁盘，各字段至少占多少位？ 2） 一个扇区的平均访问时间约为多少？ 3）若采用周期挪用DMA方式进行磁盘与主机之间的数据传送，磁盘控制器中的数据缓冲区 大小为64 位，则在一个扇区读写过程中，DMA控制器向CPU发送了多少次总线请求？ 若CPU检测到DMA控制器的总线请求信号时也需要访问主存,则DMA控制器是否可以 获得总线使用权?为什么？', NULL, '', '1）3 个字段的名称为柱面号（或磁道号）、磁头号（或盘面号）、扇区号。由于每个盘面有', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=44);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '操作系统', '综合应用', 45, '（7 分）某文件系统的磁盘块大小为4 K B ,目录项由文件名和 索引结点号构成，每个索引结点占2 5 6 字节，其中包含直接 地址项10个，一级、二级和三级间接地址项各1 个，每个地 址项占4 字节。该文件系统中子目录stu 的结构如题45（a）图 所示，stu包含子目录course和文件doc, course子目录包含 文件course 1 和course2。各文件的文件名、索引结点号、占 用磁盘块的块号如题45（b）图所示。 请回答下列问题。 第7 页（共8 页） 间接地址项？说明理由。 1）目录文件Stu中每个目录项的内容是什么？ 文件名 索引结点号 磁盘块号 2 ）文件d o c占用的磁盘块的块号x 的值是多少？ stu 1 10 3）若目录文件course的内容已在内存，则打开文 course 2 20 件c o u rsel并将其读入内存，需要读几个磁盘 coursel 10 30 块？说明理由。 course2 100 40 4 ）若文件course!的大小增长到6 M B ,则为了存 doc 10 X 取course2需要使用该文件索引结点的哪几级 题45(b)图', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=45);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '操作系统', '综合应用', 46, '（8 分）某进程的两个线程T 1 和T 2 并发执行A、B、C、D、E 和F 共6 个操作，其中T 1执行A、E 和F, T 2执行B、C 和D 。 题4 6 图表示上述6 个操作的执行顺序所必须满足的约束：C 在 A 和B 完成后执行，D 和E 在C 完成后执行，F 在E 完成后执 行。请使用信号量的wait。、signal。操作描述T 1和T 2之间的同 步关系，并说明所用信号量的作用及其初值。 题4 6 图', NULL, '', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=46);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2022, '计算机网络', '综合应用', 47, '（9 分）某网络拓扑如题4 7 图所示，R 为路由器，S 为以太网交换机，A P 是802.11接入点， 路由器的E 0接口和DHCP服务器的IP 地址配置如图中所示；H 1与H 2属于同一个广播域， 但不属于同一个冲突域；H 2和H 3属于同一个冲突域；H 4和H 5 已经接入网络，并通过DHCP 动态获取了 I P 地址。现有路由器、lOOBaseT以太网交换机和lOOBaseT集线器（Hub）三类 设备各若干台。 DHCP服务器 192.168.0.2/25 00-11-11-11-11-B1 192.168.0.4/25 00-11-11-11-11-E1 H2 H3 00-1M1-11-11-D1 题4 7 图 请回答下列问题。 1）设备1 和设备2 应该分别选择哪类设备？ 2 ）若信号传播速度为2义1。8向5 , 以太网最小帧长为64 B , 信号通过设备2 时会产生额外的 L 51尔的时间延迟，则H 2与H 3之间可以相距的最远距离是多少？ 3）在H 4 通过DHCP动态获取I P 地址过程中，H 4 首先发送了 DHCP报文M, M 是哪种 DHCP报文？路由器E 0接口能否收到封装M 的以太网帧？ S 向DHCP服务器转发的封装 M 的以太网帧的目的M AC地址是什么？ 4 ）若H 4 向H 5 发送一个IP 分组P , 则H 5 收到的封装P 的802.11帧的地址1、地址2 和地 址3 分别是什么？ 第8 页（共8 页）', NULL, '', '1 ) 设备1 选择lOOBaseT以太网交换机，设备2 选择lOOBaseT集线器。因为物理层设备既不', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2022 AND question_number=47);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '数据结构', '单选', 1, '已知带头结点的非空单链表L 的头指针为h，结点结构为 ，其中 next 是指向直 接后继结点的指针。现有指针p 和q， 若 p 指向L 中非首且非尾的任意一个结点，则执行语 句序列“q=p->next； p->next=q->next；q->next= h->next;；h->next=q；”的结果是（ ）。', '[{"key": "A", "text": "在p 所指结点后插入q 所指结点"}, {"key": "B", "text": "在q 所指结点后插入p 所指结点"}, {"key": "C", "text": "将p 所指结点移动到L 的头结点之后"}, {"key": "D", "text": "将q 所指结点移动到L 的头结点之后"}]', 'D', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=1);
