INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '数据结构', '单选', 4, '若无向图G = (V，E)的邻接多重表如下图所示，则G 中顶点b 与d 的度分别是（ ）。', '[{"key": "A", "text": "0，2"}, {"key": "B", "text": "2，4"}, {"key": "C", "text": "2，5"}, {"key": "D", "text": "3，45.下列数据结构中, 不适合直接使用折半查找的是（ ）。 data next I.有序链表 II.无序数组 III.有序静态链表 IV.无序静态链表"}, {"key": "A", "text": "仅I 、III"}, {"key": "B", "text": "仅II、IV"}, {"key": "C", "text": "仅II、III、IV"}, {"key": "D", "text": "I、II、III、IV"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=4);
