INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '数据结构', '单选', 10, '现有由关键字组成的3 个有序序列（3，5）、（7，9）和（6），若按从左至右的次序选择 有序序列进行二路归并排序， 则关键字之间的总比较次数是（ ）。', '[{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "6 在外排序中，利用败者树对初始为升序的归并段进行多路归并， 败者树中记录“冠军”的结 点保存的是（ ）。"}, {"key": "A", "text": "最大关键字"}, {"key": "B", "text": "最小关键字"}, {"key": "C", "text": "最大关键字所在的归并段号"}, {"key": "D", "text": "最小关键字所在的归并段号"}]', 'C', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=10);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机组成原理', '单选', 12, 'C 语言代码如下。 int i=32777； short si=i； int j=si； 执行上述代码段后，j 的值是（ ）。', '[{"key": "A", "text": "-32 777"}, {"key": "B", "text": "-32 759"}, {"key": "C", "text": "32 759"}, {"key": "D", "text": "32 777"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=12);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机组成原理', '单选', 13, '通常情况下，将汇编语言程序中实现特定功能的指令序列定义成一条伪指令 (pseudoinstruction)。下列选项中，CPU 能理解并直接执行的是（ ）。 I.伪指令 II.微指令 III.机器指令 IV.汇编指令', '[{"key": "A", "text": "仅I、 IV"}, {"key": "B", "text": "仅II、III"}, {"key": "C", "text": "仅III、IV"}, {"key": "D", "text": "仅I、III、IV"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=13);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机组成原理', '单选', 14, '某科学实验中，需要使用大量的整型参数，为了保证表数精度的基础上提高运算速度， 需 要选择合理的数据表示方法。若整型参数 α 、β 的取值范围分别为- 220~220、- 240~240，则下列 选项中，α 、β 最适宜采用的数据表示方法分别是（ ）。', '[{"key": "A", "text": "32 位整数、32 位整数"}, {"key": "B", "text": "单精度浮点数、单精度浮点数"}, {"key": "C", "text": "32 位整数、双精度浮点数"}, {"key": "D", "text": "单精度浮点数、双精度浮点数"}]', 'C', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=14);
