INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机组成原理', '单选', 20, '某存储器总线的时钟频率为 420MHz，总线宽度为 64 位，每个时钟周期传送 2 次数据； 其总线事务支持突发传送方式, 最多传送8 次数据，第1 个时钟周期传送地址和读/写命令，从 第4 个至第7 个时钟周期连续传送8 次数据。该总线的总线带宽（最大数据传输率)为 （ ）。 A 3.84 GB/s B. 6.72 GB/s C. 30.72 GB/s D. 53.76 GB/s', NULL, 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=20);
