INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '操作系统', '单选', 30, '假设某系统使用时间片轮转调度算法进行CPU 调度，时间片大小为5ms，系统共有10 个进 程，初始时均处于就绪队列，执行结束前仅处于执行态或就绪态。若队尾的进程P 所需CPU 时间最短，时间为25ms，在不考虑系统开销的情况下，则进程P 的周转时间为（ ）。', '[{"key": "A", "text": "200ms"}, {"key": "B", "text": "205ms"}, {"key": "C", "text": "250ms"}, {"key": "D", "text": "295ms"}]', 'C', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=30);
