INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机网络', '单选', 36, '在采用 CSMA/CA 的802.11 无线局域网中，DIFS=128μs，SIFS=28μs，RTS、CTS 和ACK 帧的传输时延分别是3μs、2μs 和2μs，忽略信号传播时延。若主机A 欲向AP 发送一个总长度 为1998 B 的数据帧，无线链路带宽为54Mb/s，则隐藏站B 收到 AP 发送的 CTS 帧时，设置 的网络分配向量NAV 的值是（ ）。', '[{"key": "A", "text": "326μs"}, {"key": "B", "text": "354μs C. 385μs"}, {"key": "D", "text": "513μs"}]', 'B', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=36);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机网络', '单选', 37, '主机甲通过选择重传(SR)滑动窗口协议向主机乙发送帧的部分过程如题37 图所示，Fx 为数 据帧，ACKx 为确认帧，x 是位数为3 比特的序号。乙只对正确接收的数据帧进行独立确认， 发送窗口与接收窗口大小相同且均为最大值。甲在t1 时刻和t2 时刻发送的数据帧分别是（ ）。', '[{"key": "A", "text": "F1，F3"}, {"key": "B", "text": "F1，F4"}, {"key": "C", "text": "F3，F1"}, {"key": "D", "text": "F4，F1"}]', 'D', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=37);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机网络', '单选', 38, '假设主机H 通过TCP 向服务器发送长度为3000B 的报文，往返时间RTT=10ms，最长报 文段寿命MSL=30s，最大报文段长度MSS=1 000 B，忽略TCP 段的传输时延，报文传输结束 后H 首先请求断开连接，则从H 请求建立TCP 连接时刻起，到H 进入 CLOSED 状态为止， 所需的时间至少是（ ）。', '[{"key": "A", "text": "30.03 s"}, {"key": "B", "text": "30.04 s"}, {"key": "C", "text": "60.03 s"}, {"key": "D", "text": "60.04 s"}]', 'D', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=38);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机网络', '单选', 39, '若UDP 协议在计算校验和过程中，计算得到中间结果为1011 1001 1011 0110 时，还需要 加上最后一个16 位数0110 0101 1100 0101，则最终计算得到的校验和是（ ）。', '[{"key": "A", "text": "0001 1111 0111 1011"}, {"key": "B", "text": "0001 1111 0111 1100"}, {"key": "C", "text": "1110 0000 1000 0011"}, {"key": "D", "text": "1110 0000 1000 0100"}]', 'C', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=39);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机网络', '单选', 40, '若浏览器不支持并行 TCP 连接，使用非持久的HTTP/1.0 协议请求浏览1 个Web 页，该 页中引用同一网站上7 个小图像文件，则从浏览器为传输 Web 页请求建立TCP 连接开始， 到接收完所有内容为止，所需要的往返时间RTT 数至少是（ ）。', '[{"key": "A", "text": "4"}, {"key": "B", "text": "9"}, {"key": "C", "text": "14"}, {"key": "D", "text": "16 二、综合应用题：41～47 小题，共70 分。"}]', 'D', '', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=40);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '数据结构', '综合应用', 41, '（13 分）2023 年10 月26 日，神州十七号载人飞船发射取得圆满成功，再次彰显了中国航 天事业的辉煌成就。载人航天工程是包含众多子工程的复杂系统工程，为了保证工程的有序开 展，需要明确各子工程的前导子工程，以协调各子工程的实施。该问题可以简化、抽象为有向 图的拓扑序列问题。已知有向图G 采用邻接矩阵存储，类型定义如下。 typedef struct //图的类型定义 { int numVertices，numEdges; //图的顶点数和有向边数 char VerticesList[MAXV]; //顶点表，MAXV 为已定义常量 int Edge[MAXV][MAXV]; //邻接矩阵 }MGraph; 请设计算法: int uniquely(MGraph G)，判定G 是否存在唯一的拓扑序列，若是，则返回1，否 则返回0。要求如下。 （1）给出算法的基本设计思想。（4 分） （2）根据设计思想，采用C 或 C++语言描述算法，关键之处给出注释。（9 分）', NULL, '', '（1）算法的基本设计思想', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=41);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '数据结构', '综合应用', 42, '（10 分）将关键字序列 20，3，11，18，9，14，7 依次存储到初始为空、长度为 11 的散 列表 HT 中，散列函数 H（key）=（key×3）%11。H（key）计算出的初始散列地址为 0 H ， 发生冲突时探查地址序列是 1 H ， 2 H ， 3 H ，…，其中， k H =（ 0 H + 2 k ）%11，k=1，2，3，…。 请回答下列问题。 （1）画出所构造的 HT，并计算 HT 的装填因子。（6 分） （2）给出在 HT 中查找关键字 14 的关键字比较序列。（2 分） （3）在 HT 中查找关键字8，确认查找失败时的散列地址是多少？（2 分）', NULL, '', '（1）HT 如下。', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=42);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机组成原理', '综合应用', 43, '（13 分）假定计算机M 字长为32 位，按字节编址，采用32 位定长指令字，指令add、slli 和1w 的格式、编码和功能说明如图43（a）图所示。 指令 31 25 24 20 19 15 14 12 11 7 6 0 指令功能说明 R[rd]←R[rs1]+ R[rs2] add R[rd]← R[rs1]<<shamt slli R[rd]← M[R[rs1]+imm] 1w 题43 图（a） 其中，R[x]表示通用寄存器x 的内容，M[x]表示地址为x 的存储单元内容，shamt 为移位位数， imm 为补码表示的偏移量。题 43 图(b)给出了计算机 M 的部分数据通路及其控制信号(用带箭 头虚线表示)，其中，A 和B 分别表示从通用寄存器rsl 和rs2 中读出的内容;IR[31:20]表示指 令寄存器中的高12 位;控制信号 Ext 为0、1 时扩展器分别实现零扩展、符号扩展，ALUctr 为 000、001、010 时 ALU 分别实现加、减、逻辑左移运算。 请回答下列问题。 （1）计算机M 最多有多少个通用寄存器？为什么 shamt 字段占5 位？（2 分） （2）执行 add 指令时，控制信号 ALUBsrc 的取值应是什么? 若rs1 和 rs2 寄存器内容分别 是 8765 4321H 和 9876 5432H，则 add 指令执行后，ALU 输出端 F、OF 和 CF 的结果分别 是什么？若该 add 指令处理的是无符号整数，则应根据哪个标志判断是否溢出？（5 分） （3）执行 slli 指令时，控制信号 Ext 的取值可以是0 也可以是 1，为什么？（2 分） （4）执行 1w 指令时，控制信号 Ext、ALUctr 的取值分别是什么？（2 分） 0000000 rs2 rs1 000 rd 0110011 0000000 shamt rs1 010 rd 0010011 imm rs1 010 rd 0000011 （5）若一条指令的机器码是 A040 A103H，则该指令一定是 1w 指令，为什么？若执行该指 令时，R[01H]=FFFF A2D0H，则所读取数据的存储地址是什么？（2 分）', NULL, '', '（1）最多有25=32 个通用寄存器。M 字长为 32 位，故通用寄存器宽度为 32 位，因此 shamt', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=43);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机组成原理', '综合应用', 44, '（10 分）对于题43 中的计算机M，C 语言程序P 包含的语句“sum+ = a[i];” 在 M 中对应的指令序列 S 如下。 slli r4，r2，2 //R[r4]←R[r2]<<2 add r4,r3,r4 //R[r4]←R[r3]+R[r4] 1w r5,0(r4) //R[r5]←M[R[r4]+0] add rl,rl, r5 //R[r1]←R[r1]+R[r5] 已知变量 i、sum 和数组a 都为 int 型，通用寄存器 r1~r5 的编号为 01H~05H。 请回答下列问题。 （1）根据指令序列S 中每条指令的功能，写出存放数组a 的首地址、变量i 和sum 的通用寄 存器编号。（3 分） （2）已知 M 为小端方式计算机，采用页式存储管理方式，页大小为4KB。若执行到指令序列 S 中第1 条指令时，i=5 且r1 和 r3 的内容分别为0000 1332H 和0013 DFF0H，从地址0013 DFF0H 开始的存储单元内容如题 44 图所示，则执行“sum+ =a[i];”语句后，a[i]的地址、a[i] 和sum 的机器数分别是什么（用十六进制表示）？a[i]所在页的页号是多少？此次执行中，数 组a 至少存放在子页中？（5 分） 地址 0 1 2 3 4 5 6 7 0013 DFF0 0013 DFF8 0013 E000 0013 E008 题 44 图 （3）指令“slli r4，r2，2”的机器码是什么（用十六进制表示）？若数组a 改为 short 类型，则 指令序列S 中 slli 指令的汇编形式应是什么？（2 分） FF FF FF 7C 70 FE FF FF 00 00 00 0C 3C 02 01 FF F0 F1 00 00 DC EC FF FF FF FF 01 02 00 00 01 02', NULL, '', '（1）a 的首地址存放在 r3；i 存放在 r2；sum 存放在 r1。', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=44);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '操作系统', '综合应用', 45, '（7 分）某计算机按字节编址，采用页式虚拟存储管理方式，虚拟地址和物理地址的长度均 为 32 位，页表项的大小为4 字节。页大小为4 MB，虚拟地址结构如下。 页号（10 位） 页内偏移量（22 位） 进程P 的页表起始虚拟地址为 B8C0 0000H，被装载到从物理地址 6540 0000H 开始的连续主 存空间中。 请回答下列问题，要求答案用十六进制表示。 （1）若CPU 在执行进程P 的过程中，访问虚拟地址 1234 5678H 时发生了缺页异常，经过缺 页异常处理和 MMU 地址转换后得到的物理地址是 BAB4 5678H，在此次缺页异常处理过程 中，需要为所缺页分配页框并更新相应的页表项，则该页表项的虚拟地址和物理地址分别是什 么？该页表项中的页框号更新后的值是什么？（3 分） （2）进程P 的页表所在页的页号是什么？该页对应的页表项的虚拟地址是什么？该页表项中 的页框号是什么？（4 分）', NULL, '', '（1）页表项的虚拟地址为： B8C0 0000H+ 48H << 2 = B8C0 0120H。', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=45);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '操作系统', '综合应用', 46, '（8 分）计算机系统中的进程之间往往需要相互协作以完成一个任务。在某网络系统中，缓 冲区 B 用于存放一个数据分组，对B 的操作有 C1、C2 和 C3。C1 将一个数据分组写入B 中，C2 从 B 中读出一个数据分组，C3 对B 中的数据分组进行修改。要求 B 为空时才能执行 C1，B 非空时才能执行C2 和C3。 请回答下列问题。 （1）假设进程 P1 和 P2 均需要执行 C1，实现 C1 的代码是否为临界区？为什么？（2 分） （2）假设B 初始为空，进程 P1 执行 C1 一次，进程 P2 执行 C2 一次。请定义尽可能少的 信号量，并用 wait（）、signal（）操作描述进程 P1 和 P2 之间的同步或互斥关系，说明所 用信号量的作用及其初值。（3 分） （3）假设 B 初始不为空，进程 P1 和 P2 各执行 C3 一次。请定义尽可能少的信号量，并用 wait（）、signal（）操作描述进程P1 和 P2 之间的同步或互斥关系，说明所用信号量的作用 及其初值。（3 分）', NULL, '', '（1）实现C1 的代码是临界区。因为代码 C1 执行对B 的写操作，且 P1 和 P2 需要互斥执行', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=46);
INSERT INTO question (year, subject, type, question_number, content, options, answer, analysis, knowledge_tag) SELECT 2024, '计算机网络', '综合应用', 47, '（9 分）网络空间是继陆海空天之后的“第五疆域”，网络技术是网络疆域建设与治理的基 础。路由算法与协议是网络核心技术之一，对其准确认知、合理选择与应用，对于网络建设十 分重要。假设现有互联网中的4 个自治系统互连拓扑示意图如题47 图所示。其中，AS1 运行 内部网关协议RIP；AS3 规模较小，自治系统内任意两个主机间通信，经过路由器数量不超过 15 个；AS4 规模较大，自治系统内任意两个主机间通信，经过路由器数量可能超过20 个。 请回答下列问题。 （1）若仅有 RIP 和 OSPF 内部网关协议供选择，则 AS4 应该选择哪个协议？（1 分） （2）若AS3 中的某主机向本自治系统内另一主机发送1 个IP 分组，为确保该 IP 分组能够被 正常接收，则该 IP 分组的初始TTL 值应该至少设置为多少？（1 分） （3）假设 AS1 中的路由器同一时刻启动，启动后立即构建并交换初始距离向量，之后每隔 30s 交换一次最新的距离向量，则从交换初始距离向量时刻算起，R11~R16 路由器均获得到达 网络 210.2.3.0/24 的正确路由，至少需要多长时间？均获得到达网络 210.2.4.0/24 的正确路由， 至少需要多长时间？（2 分） （4）R44 向 R13 通告到达网络 136.5.16.0/20 路由时，由 BGP 协议哪类会话完成？通过哪 个 BGP 报文通告？R13 通过BGP 协议的哪类会话将该网络可达性信息通告给R14 和R15？ （3 分） （5）若 R14 和 R15 均收到分别由 R11、R12、R13 通告的到达网络 136.5.16.0/20 的可达性 信息如下。 目的网络:136.5.16.0/20，AS 路径:AS2 AS8 AS19， 下一跳:R11 目的网络:136.5.16.0/20，AS 路径:AS3 AS7 AS11 AS19, 下一跳:R12 目的网络:136.5.16.0/20，AS 路径:AS4 AS10 AS19， 下一跳:R13 则在无策略约束情况下，R14 和 R15 更新路由表后，各自路由表中到达网络 136.5.16.0/20 路 由的下一跳分别是什么（用路由器名称表示）？（2 分） 2024 年全国硕士研究生入学统一考试 计算机科学与技术学科联考 计算机学科专业基础综合试题（答案速查） 一、单项选择题', NULL, '', '（1）AS4 应该选择 OSPF 协议。', '' WHERE NOT EXISTS (SELECT 1 FROM question WHERE year=2024 AND question_number=47);
